ALTER TABLE users ADD COLUMN display_name varchar(120) NOT NULL DEFAULT '', ADD COLUMN role varchar(16) NOT NULL DEFAULT 'owner', ADD COLUMN permissions jsonb NOT NULL DEFAULT '[]', ADD COLUMN active boolean NOT NULL DEFAULT true, ADD COLUMN token_version integer NOT NULL DEFAULT 0;
UPDATE users SET display_name = username;
ALTER TABLE users ALTER COLUMN role SET DEFAULT 'admin';
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK (role IN ('owner', 'admin')), ADD CONSTRAINT users_permissions_array CHECK (jsonb_typeof(permissions) = 'array');
ALTER TABLE projects ADD COLUMN client_en varchar(120) NOT NULL DEFAULT '';
ALTER TABLE services ADD COLUMN published boolean NOT NULL DEFAULT true;
ALTER TABLE services ALTER COLUMN published SET DEFAULT false;
CREATE TABLE articles (id serial PRIMARY KEY, slug varchar(120) NOT NULL UNIQUE, category varchar(32) NOT NULL CHECK (category IN ('product','engineering','growth')), published_at varchar(10) NOT NULL, published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, sources jsonb NOT NULL DEFAULT '[]', translations jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX articles_public_order_idx ON articles (sort_order, id) WHERE published;
CREATE TABLE task_stages (id serial PRIMARY KEY, name varchar(120) NOT NULL, name_ar varchar(120) NOT NULL DEFAULT '', name_ckb varchar(120) NOT NULL DEFAULT '', color varchar(7) NOT NULL DEFAULT '#6366F1', sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE tasks (id serial PRIMARY KEY, title varchar(200) NOT NULL, description text NOT NULL DEFAULT '', stage_id integer NOT NULL REFERENCES task_stages(id) ON DELETE RESTRICT, assignee_id integer REFERENCES users(id) ON DELETE RESTRICT, created_by_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, sort_order integer NOT NULL DEFAULT 0, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tasks_stage_order_idx ON tasks (stage_id, sort_order, id) WHERE NOT archived;
CREATE INDEX tasks_assignee_idx ON tasks (assignee_id);
CREATE INDEX tasks_creator_idx ON tasks (created_by_id);
CREATE TABLE task_comments (id serial PRIMARY KEY, task_id integer NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT, author_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX task_comments_task_idx ON task_comments (task_id, created_at, id);
CREATE INDEX task_comments_author_idx ON task_comments (author_id);
INSERT INTO task_stages (name,name_ar,name_ckb,color,sort_order) VALUES ('To do','للعمل','بۆ ئەنجامدان','#717F95',0),('In progress','قيد التنفيذ','لە جێبەجێکردندایە','#6366F1',1),('Done','مكتمل','تەواوبوو','#16A34A',2);
INSERT INTO articles (slug,category,published_at,published,sort_order,sources,translations) VALUES ('before-building-a-website-or-app','product','2026-09-06',true,0,'[{"id": "discovery", "title": "GOV.UK Service Manual — How the discovery phase works", "url": "https://www.gov.uk/service-manual/agile-delivery/how-the-discovery-phase-works"}, {"id": "research", "title": "GOV.UK Service Manual — User research in discovery", "url": "https://www.gov.uk/service-manual/user-research/user-research-in-discovery"}, {"id": "research-plan", "title": "GOV.UK Service Manual — Plan user research for your service", "url": "https://www.gov.uk/service-manual/user-research/plan-user-research-for-your-service"}, {"id": "alpha", "title": "GOV.UK Service Manual — How the alpha phase works", "url": "https://www.gov.uk/service-manual/agile-delivery/how-the-alpha-phase-works"}, {"id": "benefits", "title": "GOV.UK Service Manual — Measuring the benefits of your service", "url": "https://www.gov.uk/service-manual/measuring-success/measuring-service-benefits"}]'::jsonb,'{"en": {"title": "Before building a website or app: a founder’s discovery checklist", "description": "Validate a user problem, define a practical MVP, prepare a useful project brief, and decide how to measure your website or app after launch.", "excerpt": "A clear feature list is useful only when it solves a real problem. Use this guide to turn an idea into a testable brief before committing to development.", "takeaways": ["Describe the user’s task and current difficulty before choosing screens or technology.", "Keep the first release small while preserving a complete, dependable user journey.", "Agree on launch measures, operational ownership, and reasons to change direction."], "sections": [{"id": "define-outcome", "heading": "Start with an outcome someone needs", "paragraphs": ["A project often begins with a proposed solution: an app for customers, a marketplace, or a redesigned website. Rewrite that idea as a task: who needs to achieve what, in which situation, and what currently prevents them? GOV.UK’s discovery guidance recommends understanding the problem before committing to a service.", "Consider a hypothetical Baghdad repair business. Customers repeatedly call to check whether a technician is available. The desired outcome might be a confirmed appointment without repeated calls. That does not yet determine whether the answer is a booking page, a better internal schedule, or a mobile app. Write down the outcome and keep those options open."], "sourceIds": ["discovery"]}, {"id": "observe-behavior", "heading": "Collect evidence from current behaviour", "paragraphs": ["Speak with people who actually encounter the problem, including staff who handle exceptions. GOV.UK’s research guidance includes examining the current journey and involving people with different abilities and support needs. Ask participants to describe a recent incident, then, with permission, show how they dealt with it.", "Useful prompts include: What started the task? Which information was missing? When did you ask someone for help? What happened after you submitted the request? Record concrete steps and consequences. A compliment about your idea is weaker evidence than a repeated difficulty. For an Arabic, English, and Sorani service, test the task in the languages people use; language preference should not be guessed from location."], "sourceIds": ["research"]}, {"id": "test-assumptions", "heading": "Test the assumptions that could invalidate the project", "paragraphs": ["GOV.UK recommends turning unsupported assumptions into research questions; its alpha guidance uses prototypes to explore risky parts of a solution. Apply that approach to your own decision, without copying government delivery timelines.", "List assumptions such as customers accepting a booking deposit, staff keeping availability current, or an existing system exposing usable data. Rank them by the damage caused if they are false. A clickable booking prototype can test comprehension. A supervised manual booking trial can reveal staff workload. A technical experiment can test an integration. These are different tests: a usable prototype does not prove demand, and an integration demo does not prove that customers will return."], "sourceIds": ["research-plan", "alpha"]}, {"id": "scope-mvp", "heading": "Scope one complete journey for the first release", "paragraphs": ["Define your minimum viable product, or MVP, as the smallest release that can deliver the chosen outcome and answer a business question. For the repair example, that could mean choosing a service, requesting a time, receiving confirmation, and changing or cancelling the request. Include the staff action that makes confirmation real.", "Separate essentials, later improvements, and explicit exclusions. A loyalty programme might wait; clear error messages and protection of customer data should be part of the relevant work. If confirmation remains manual, say so in the interface and agree who handles it. Reducing scope means serving fewer needs well, while making the limits understandable."]}, {"id": "write-brief", "heading": "Prepare a brief that supports an honest estimate", "paragraphs": ["A useful brief exposes decisions and uncertainties. It does not need to predict every screen. Use this numbered checklist before asking a development partner for a proposal:"], "bullets": ["1. Outcome and audience: identify the primary user, their task, and the evidence that the problem matters.", "2. First-release journey: describe entry, completion, failure, cancellation, and the staff workflow.", "3. Content and languages: name who supplies, translates, checks, and updates text and images.", "4. Data and integrations: list existing systems, access owners, required fields, and unresolved dependencies.", "5. Constraints: state budget boundaries, the reason for any deadline, supported devices, and accessibility needs.", "6. Acceptance and ownership: define what must be demonstrated, who approves it, and who operates the service after handover."]}, {"id": "operating-work", "heading": "Include the work around the software", "paragraphs": ["A booking form can work perfectly while the service fails because nobody reads the requests. Walk through an ordinary day and a difficult day: a staff member is absent, a customer enters the wrong phone number, or an external service becomes unavailable. Assign responsibility for each case before launch.", "Also agree who controls the domain, hosting, source repository, analytics, and third-party accounts. Identify the recurring work: content updates, access reviews, backups and recovery checks, support, and technical maintenance. Ask proposals to separate initial delivery from ongoing operations and to name assumptions behind estimates. The cheaper first invoice is not enough information to compare two approaches."]}, {"id": "measure-launch", "heading": "Decide what launch should teach you", "paragraphs": ["GOV.UK’s benefits guidance recommends establishing a baseline before assessing improvement. For your project, record the current result where possible, then choose a small set of measures tied to the outcome.", "For the repair example, track completed appointment requests, confirmed appointments, time to confirmation, and requests needing staff correction. Define each measure: a submitted form is not necessarily a confirmed booking. Review abandonment alongside interviews or support feedback so the numbers have context. Avoid collecting personal data merely because an analytics tool allows it.", "Choose a review date, an owner, and a decision rule before launch. Evidence may justify improving a confusing step, expanding the service, keeping a manual process, or pausing further development. Traffic alone cannot tell you which choice is right."], "sourceIds": ["benefits"]}], "conclusion": "Before commissioning development, bring a problem statement, research notes, a bounded first-release journey, and a measurement plan. Those materials give you and your software partner a concrete basis for deciding what to build, what to test first, and what success would mean."}, "ar": {"title": "قبل بناء موقع أو تطبيق: قائمة عملية لاكتشاف احتياجات المشروع", "description": "تحقّق من مشكلة المستخدم، وحدّد نطاق النسخة الأولى، وجهّز موجزاً واضحاً للمشروع وخطة لقياس النتائج بعد إطلاق الموقع أو التطبيق.", "excerpt": "تكون قائمة المزايا مفيدة حين تعالج مشكلة حقيقية. يساعدك هذا الدليل على تحويل الفكرة إلى موجز يمكن اختباره قبل الالتزام بتطويرها.", "takeaways": ["صِف مهمة المستخدم والصعوبة التي يواجهها قبل اختيار الشاشات أو التقنية.", "قلّص نطاق الإصدار الأول مع الحفاظ على رحلة استخدام مكتملة ويمكن الاعتماد عليها.", "اتفق على مقاييس الإطلاق ومسؤوليات التشغيل والأدلة التي قد تستدعي تغيير الاتجاه."], "sections": [{"id": "define-outcome", "heading": "ابدأ بنتيجة يحتاجها شخص فعلي", "paragraphs": ["تبدأ مشاريع كثيرة بحلّ مقترح: تطبيق للعملاء، أو سوق إلكترونية، أو إعادة تصميم موقع. أعد صياغة الفكرة بوصفها مهمة: من يريد إنجاز ماذا، وفي أي ظرف، وما الذي يمنعه الآن؟ توصي إرشادات مرحلة الاستكشاف في GOV.UK بفهم المشكلة قبل الالتزام ببناء الخدمة.", "لنتخيّل شركة صيانة في بغداد يتصل عملاؤها مراراً للاستفسار عن توافر الفنيين. قد تكون النتيجة المطلوبة حجز موعد مؤكّد دون اتصالات متكررة. لكن ذلك لا يحسم ما إذا كان الحل صفحة حجز، أو جدولاً داخلياً أفضل، أو تطبيقاً للهاتف. دوّن النتيجة المطلوبة واترك البدائل مفتوحة إلى أن تتوافر أدلة تساعدك على الاختيار."], "sourceIds": ["discovery"]}, {"id": "observe-behavior", "heading": "اجمع أدلة من السلوك الحالي", "paragraphs": ["تحدّث مع أشخاص يواجهون المشكلة فعلاً، ومع الموظفين الذين يعالجون الحالات الاستثنائية. تتناول إرشادات البحث في GOV.UK دراسة رحلة الاستخدام الحالية وإشراك أشخاص تختلف قدراتهم واحتياجاتهم إلى المساعدة. اطلب من المشاركين وصف موقف حديث، ثم توضيح الطريقة التي تعاملوا بها معه، بعد أخذ موافقتهم.", "اسأل مثلاً: ما الذي دفعك إلى بدء المهمة؟ ما المعلومات التي كانت ناقصة؟ متى طلبت المساعدة؟ ماذا حدث بعد إرسال الطلب؟ سجّل الخطوات الفعلية وآثارها. الإعجاب بفكرتك دليل أضعف من صعوبة متكررة يمكن وصفها. وإذا كانت الخدمة بالعربية والإنجليزية والسورانية، فاختبر المهمة باللغات التي يستخدمها الناس؛ لا تفترض لغتهم المفضلة اعتماداً على موقعهم."], "sourceIds": ["research"]}, {"id": "test-assumptions", "heading": "اختبر الافتراضات التي قد تغيّر جدوى المشروع", "paragraphs": ["توصي GOV.UK بتحويل الافتراضات غير المدعومة إلى أسئلة بحثية، وتستخدم إرشادات مرحلة ألفا النماذج الأولية لاستكشاف جوانب الحل الأكثر مخاطرة. استفد من هذا الأسلوب في قرارك، دون أن تنقل الجداول الزمنية الخاصة بالمشاريع الحكومية إلى مشروعك.", "اكتب افتراضات مثل قبول العملاء دفع عربون للحجز، أو التزام الموظفين بتحديث المواعيد المتاحة، أو إمكانية الحصول على بيانات من النظام الحالي. رتّبها بحسب الضرر إذا تبيّن أنها خاطئة. يمكن لنموذج حجز تفاعلي اختبار وضوح الخطوات، ولتجربة حجز يدوي تحت الإشراف إظهار عبء العمل، ولتجربة تقنية فحص التكامل. لكل اختبار سؤال مختلف: سهولة استخدام النموذج لا تثبت الطلب على الخدمة، ونجاح التكامل لا يثبت أن العملاء سيعودون."], "sourceIds": ["research-plan", "alpha"]}, {"id": "scope-mvp", "heading": "حدّد رحلة مكتملة واحدة للإصدار الأول", "paragraphs": ["عرّف المنتج الأولي القابل للاستخدام، أو MVP، بأنه أصغر إصدار يحقّق النتيجة المطلوبة ويساعد على الإجابة عن سؤال تجاري. في مثال الصيانة، قد يشمل اختيار الخدمة وطلب موعد واستلام التأكيد وتغيير الطلب أو إلغاءه. أدرج أيضاً إجراء الموظف الذي يجعل تأكيد الموعد فعلياً.", "افصل بين الضروريات والتحسينات اللاحقة وما يُستبعد صراحةً. قد ينتظر برنامج الولاء، بينما ينبغي إدراج رسائل الخطأ الواضحة وحماية بيانات العملاء ضمن العمل ذي الصلة. وإذا بقي التأكيد يدوياً، فأوضح ذلك في الواجهة وحدّد المسؤول عنه. تقليص النطاق يعني تلبية احتياجات أقل بإتقان، مع جعل حدود الخدمة مفهومة."]}, {"id": "write-brief", "heading": "جهّز موجزاً يسمح بتقدير واقعي", "paragraphs": ["يكشف الموجز المفيد القرارات والنقاط غير المحسومة، ولا يحتاج إلى توقّع كل شاشة. استخدم هذه القائمة قبل طلب عرض من شريك تطوير:"], "bullets": ["١. النتيجة والجمهور: حدّد المستخدم الأساسي ومهمته والأدلة على أهمية المشكلة.", "٢. رحلة الإصدار الأول: صِف البداية والإنجاز والفشل والإلغاء وسير عمل الموظفين.", "٣. المحتوى واللغات: سمِّ المسؤول عن توفير النصوص والصور وترجمتها ومراجعتها وتحديثها.", "٤. البيانات والتكاملات: اذكر الأنظمة الحالية وأصحاب صلاحيات الوصول والحقول المطلوبة والاعتماديات التي لم تُحسم.", "٥. القيود: وضّح حدود الميزانية وسبب أي موعد نهائي والأجهزة المدعومة واحتياجات إمكانية الوصول.", "٦. القبول والمسؤولية: حدّد ما يجب إثباته عملياً، ومن يعتمد التسليم، ومن يشغّل الخدمة بعده."]}, {"id": "operating-work", "heading": "احسب العمل الذي يحيط بالبرنامج", "paragraphs": ["قد يعمل نموذج الحجز جيداً وتفشل الخدمة لأن أحداً لا يقرأ الطلبات. مرّ على سيناريو ليوم عادي وآخر صعب: غياب موظف، أو إدخال العميل رقم هاتف خاطئ، أو تعطل خدمة خارجية. وزّع مسؤولية معالجة كل حالة قبل الإطلاق.", "اتفق أيضاً على من يتحكم بالنطاق والاستضافة ومستودع الشيفرة والتحليلات وحسابات الأطراف الخارجية. حدّد الأعمال المتكررة: تحديث المحتوى، ومراجعة الصلاحيات، والنسخ الاحتياطي والتحقق من الاستعادة، والدعم، والصيانة التقنية. اطلب أن تفصل العروض بين التسليم الأولي والتشغيل المستمر، وأن توضّح الافتراضات التي تستند إليها التقديرات. انخفاض الفاتورة الأولى وحده لا يكفي لمقارنة نهجين."]}, {"id": "measure-launch", "heading": "قرّر ما الذي تريد تعلّمه من الإطلاق", "paragraphs": ["توصي إرشادات قياس المنافع في GOV.UK بتسجيل خط أساس قبل تقييم التحسن. سجّل نتيجة العملية الحالية حيثما أمكن، ثم اختر مجموعة صغيرة من المقاييس المرتبطة بالنتيجة المطلوبة.", "في مثال الصيانة، راقب طلبات المواعيد المكتملة والمواعيد المؤكّدة والوقت اللازم للتأكيد والطلبات التي تحتاج إلى تصحيح من الموظفين. عرّف كل مقياس بدقة: إرسال النموذج لا يعني بالضرورة تأكيد الحجز. راجع التوقف عن إكمال الخطوات إلى جانب المقابلات أو ملاحظات الدعم لفهم الأرقام في سياقها. لا تجمع بيانات شخصية لمجرد أن أداة التحليلات تتيح جمعها.", "حدّد قبل الإطلاق موعداً للمراجعة ومسؤولاً عنها وقاعدة لاتخاذ القرار. قد تبرر الأدلة تحسين خطوة مربكة، أو توسيع الخدمة، أو الإبقاء على إجراء يدوي، أو إيقاف التطوير الإضافي مؤقتاً. عدد الزيارات وحده لا يحدّد الخيار المناسب."], "sourceIds": ["benefits"]}], "conclusion": "قبل التعاقد على التطوير، جهّز وصفاً للمشكلة وملاحظات البحث ورحلة محددة للإصدار الأول وخطة للقياس. تمنحك هذه المواد أنت وشريكك التقني أساساً عملياً لتحديد ما ينبغي بناؤه، وما يجب اختباره أولاً، وما الذي يعنيه النجاح."}, "ckb": {"title": "پێش دروستکردنی ماڵپەڕ یان ئەپ: ڕێنمایەکی کرداری بۆ ناسینی پێداویستییەکانی پڕۆژە", "description": "کێشەی بەکارهێنەر پشتڕاست بکەرەوە، سنووری وەشانی یەکەم دیاری بکە و پوختەیەکی ڕوون و پلانی پێوانەکردن بۆ ماڵپەڕ یان ئەپەکەت ئامادە بکە.", "excerpt": "لیستی تایبەتمەندییەکان کاتێک بەسوودە کە کێشەیەکی ڕاستەقینە چارەسەر بکات. ئەم ڕێنماییە یارمەتیت دەدات پێش دەستپێکردنی گەشەپێدان، بیرۆکەکەت بگۆڕیت بۆ پوختەیەکی تاقیکردنەوە.", "takeaways": ["پێش هەڵبژاردنی شاشە و تەکنەلۆژیا، ئەرکی بەکارهێنەر و ئەو دژوارییە بنووسە کە ئێستا ڕووبەڕووی دەبێتەوە.", "سنووری وەشانی یەکەم بچووک بکەرەوە، بەڵام ڕێڕەوی بەکارهێنانەکە تەواو و جێی متمانە بێت.", "لەسەر پێوەرەکانی بڵاوکردنەوە، بەرپرسیارییەکانی بەڕێوەبردن و هۆکارەکانی گۆڕینی ئاراستە ڕێک بکەون."], "sections": [{"id": "define-outcome", "heading": "بە ئەنجامێک دەست پێ بکە کە کەسێک پێویستی پێیەتی", "paragraphs": ["زۆر پڕۆژە بە چارەسەرێکی پێشنیارکراو دەست پێ دەکات: ئەپێک بۆ کڕیاران، بازاڕێکی ئۆنلاین، یان دیزاینکردنەوەی ماڵپەڕێک. بیرۆکەکە وەک ئەرکێک دابڕێژەوە: کێ دەیەوێت چی بکات، لە چ بارودۆخێکدا، و ئێستا چی ڕێگری لێ دەکات؟ ڕێنمایی قۆناغی دۆزینەوەی GOV.UK پێشنیار دەکات پێش بڕیاردان لەسەر دروستکردنی خزمەتگوزارییەکە، کێشەکە تێبگەیت.", "بۆ نموونە، کۆمپانیایەکی گریمانەیی چاککردنەوە لە بەغدا لەبەرچاو بگرە کە کڕیارەکانی دووبارە پەیوەندی دەکەن بۆ زانینی کاتی بەردەستی تەکنیککار. ئەنجامی خوازراو لەوانەیە وەرگرتنی کاتێکی پشتڕاستکراو بێت بەبێ پەیوەندیی دووبارە. ئەمە هێشتا دیاری ناکات کە چارەسەرەکە پەڕەی حجزکردنە، خشتەیەکی باشترە بۆ ناوخۆ، یان ئەپی مۆبایلە. ئەنجامەکە بنووسە و هەڵبژاردەکان بە کراوەیی بهێڵەوە."], "sourceIds": ["discovery"]}, {"id": "observe-behavior", "heading": "بەڵگە لە ڕەفتاری ئێستا کۆ بکەرەوە", "paragraphs": ["لەگەڵ کەسانێک بدوێ کە بەڕاستی تووشی کێشەکە دەبن، هەروەها ئەو کارمەندانەی حاڵەتە نائاساییەکان چارەسەر دەکەن. ڕێنمایی توێژینەوەی GOV.UK لێکۆڵینەوە لە ڕێڕەوی ئێستا و بەشداریپێکردنی کەسانی خاوەن توانایی و پێداویستیی جیاواز بۆ یارمەتی دەگرێتەوە. داوا لە بەشداربووان بکە باس لە ڕووداوێکی نوێ بکەن، پاشان بە ڕەزامەندییان نیشانت بدەن چۆن مامەڵەیان لەگەڵ کردووە.", "دەتوانیت بپرسیت: چی وای کرد دەست بە ئەرکەکە بکەیت؟ چ زانیارییەک کەم بوو؟ کەی داوای یارمەتیت کرد؟ دوای ناردنی داواکارییەکە چی ڕوویدا؟ هەنگاوە ڕاستەقینەکان و ئەنجامەکانیان تۆمار بکە. پەسەندکردنی بیرۆکەکەت بەڵگەیەکی لاوازترە لە دژوارییەک کە دووبارە دەبێتەوە. ئەگەر خزمەتگوزارییەکە بە عەرەبی، ئینگلیزی و سۆرانییە، ئەرکەکە بەو زمانانە تاقی بکەرەوە کە خەڵک بەکاریان دەهێنن؛ تەنها لە شوێنی ژیانیانەوە زمانە پەسەندکراوەکەیان مەخەمڵێنە."], "sourceIds": ["research"]}, {"id": "test-assumptions", "heading": "ئەو گریمانانە تاقی بکەرەوە کە دەتوانن بڕیاری پڕۆژەکە بگۆڕن", "paragraphs": ["GOV.UK پێشنیار دەکات گریمانە بێ‌بەڵگەکان بگۆڕدرێن بۆ پرسیاری توێژینەوە؛ ڕێنمایی قۆناغی ئەلفاش نموونە سەرەتاییەکان بۆ پشکنینی بەشە پڕمەترسییەکانی چارەسەر بەکار دەهێنێت. ئەم ڕێبازە بۆ بڕیارەکەی خۆت بەکار بهێنە، بەبێ ئەوەی خشتەی کاتی پڕۆژە حکومییەکان کۆپی بکەیت.", "گریمانەکان بنووسە؛ وەک ئەوەی کڕیاران ئامادەن پێشەکی بۆ حجز بدەن، کارمەندان کاتە بەردەستەکان نوێ دەکەنەوە، یان سیستەمی ئێستا داتای بەکارهاتوو دەدات. بەپێی زیانی هەڵەبوونیان ڕیزبەندییان بکە. نموونەیەکی کلیک‌پێکراوی حجزکردن دەتوانێت ڕوونیی هەنگاوەکان تاقی بکاتەوە. تاقیکردنەوەی حجزکردنی دەستی بە چاودێری دەتوانێت باری کاری کارمەندان دەربخات، و تاقیکردنەوەیەکی تەکنیکی دەتوانێت پەیوەستکردنی سیستەمەکان بپشکنێت. ئەمانە تاقیکردنەوەی جیاوازن: ئاسانیی نموونەکە داواکاریی بازاڕ ناسەلمێنێت و سەرکەوتنی پەیوەستکردنەکە ناسەلمێنێت کە کڕیاران دەگەڕێنەوە."], "sourceIds": ["research-plan", "alpha"]}, {"id": "scope-mvp", "heading": "بۆ وەشانی یەکەم یەک ڕێڕەوی تەواو دیاری بکە", "paragraphs": ["بەرهەمی سەرەتایی بە کەمترین تایبەتمەندیی پێویست، یان MVP، وەک بچووکترین وەشان پێناسە بکە کە ئەنجامی هەڵبژێردراو بەدەست بهێنێت و وەڵامی پرسیارێکی بازرگانی بداتەوە. لە نموونەی چاککردنەوەدا، ئەمە دەتوانێت هەڵبژاردنی خزمەتگوزاری، داواکردنی کات، وەرگرتنی پشتڕاستکردنەوە و گۆڕین یان هەڵوەشاندنەوەی داواکاری بگرێتەوە. ئەو هەنگاوەی کارمەندیش تێدا بێت کە کاتەکە بەڕاستی پشتڕاست دەکاتەوە.", "پێویستییەکان، باشترکردنەکانی دواتر و ئەو شتانەی بە ڕوونی لە سنوورەکە دەرەوەن لێک جیا بکەرەوە. بەرنامەی پاداشتی کڕیاران دەتوانێت دوا بخرێت؛ بەڵام پەیامی هەڵەی ڕوون و پاراستنی داتای کڕیاران دەبێت بەشێک بن لە کاری پەیوەندیدار. ئەگەر پشتڕاستکردنەوەکە هێشتا دەستییە، لە ڕووکاردا ڕوونی بکەرەوە و بەرپرسەکەی دیاری بکە. بچووککردنەوەی سنوور واتە ژمارەیەکی کەمتر لە پێداویستییەکان باش جێبەجێ بکەیت و سنوورەکان تێگەیشتنیان ئاسان بێت."]}, {"id": "write-brief", "heading": "پوختەیەک ئامادە بکە کە خەمڵاندنی ڕاستبینانە بکرێت", "paragraphs": ["پوختەیەکی بەسوود بڕیارەکان و خاڵە نادیارەکان دەخاتە ڕوو. پێویست ناکات هەموو شاشەکان پێشبینی بکات. پێش داواکردنی پێشنیار لە هاوبەشێکی گەشەپێدان ئەم لیستە بەکار بهێنە:"], "bullets": ["١. ئەنجام و بەکارهێنەر: بەکارهێنەری سەرەکی، ئەرکەکەی و بەڵگەی گرنگیی کێشەکە دیاری بکە.", "٢. ڕێڕەوی وەشانی یەکەم: دەستپێک، تەواوکردن، شکستهێنان، هەڵوەشاندنەوە و ڕەوتی کاری کارمەندان باس بکە.", "٣. ناوەڕۆک و زمان: دیاری بکە کێ دەق و وێنە دابین دەکات، وەریاندەگێڕێت، پێداچوونەوەیان بۆ دەکات و نوێیان دەکاتەوە.", "٤. داتا و پەیوەستکردن: سیستەمە هەنووکەییەکان، خاوەنی مۆڵەتی دەستگەیشتن، خانە پێویستەکان و پێداویستییە چارەسەرنەکراوەکان بنووسە.", "٥. سنووردارییەکان: سنووری بودجە، هۆکاری کاتی کۆتایی، ئامێرە پشتگیریکراوەکان و پێداویستییەکانی دەستڕاگەیشتن ڕوون بکەرەوە.", "٦. وەرگرتن و بەرپرسیاری: دیاری بکە چی دەبێت بەکردەوە نیشان بدرێت، کێ پەسەندی دەکات و کێ دوای ڕادەستکردن خزمەتگوزارییەکە بەڕێوە دەبات."]}, {"id": "operating-work", "heading": "ئەو کارانەش بژمێرە کە لە دەوری نەرمەکاڵاکەن", "paragraphs": ["فۆڕمی حجزکردن دەتوانێت بەباشی کار بکات، بەڵام خزمەتگوزارییەکە سەرنەکەوێت چونکە کەس داواکارییەکان ناخوێنێتەوە. ڕۆژێکی ئاسایی و ڕۆژێکی دژوار بە هەنگاوەکاندا ببە: کارمەندێک ئامادە نییە، کڕیارێک ژمارەی تەلەفۆنی هەڵە دەنووسێت، یان خزمەتگوزارییەکی دەرەکی بەردەست نییە. پێش بڵاوکردنەوە بەرپرسیاریی هەر حاڵەتێک دیاری بکە.", "هەروەها ڕێک بکەون کێ کۆنترۆڵی دۆمەین، هۆستینگ، کۆگای کۆد، ئامرازەکانی شیکاری و هەژمارەکانی لایەنی سێیەم دەکات. کارە دووبارەبووەکان بناسە: نوێکردنەوەی ناوەڕۆک، پێداچوونەوە بە دەسەڵاتەکان، پاشەکەوت و پشکنینی گەڕاندنەوە، پشتیوانی و چاکسازیی تەکنیکی. داوا بکە پێشنیارەکان ڕادەستکردنی سەرەتایی لە بەڕێوەبردنی بەردەوام جیا بکەنەوە و گریمانەکانی پشت خەمڵاندنەکان دیاری بکەن. هەرزانتر بوونی پسووڵەی یەکەم بە تەنها بۆ بەراوردکردنی دوو ڕێباز بەس نییە."]}, {"id": "measure-launch", "heading": "دیاری بکە لە بڵاوکردنەوە چی فێر دەبیت", "paragraphs": ["ڕێنمایی پێوانەکردنی سوودەکانی GOV.UK پێشنیار دەکات پێش هەڵسەنگاندنی باشترکردن، بنەمایەکی بەراورد تۆمار بکرێت. بۆ پڕۆژەکەت، تا دەکرێت ئەنجامی ئێستا بنووسە و پاشان ژمارەیەکی کەم لە پێوەرە پەیوەندیدارەکان بە ئەنجامی خوازراو هەڵبژێرە.", "لە نموونەی چاککردنەوەدا، داواکارییە تەواوکراوەکان، کاتە پشتڕاستکراوەکان، ماوەی چاوەڕوانی بۆ پشتڕاستکردنەوە و داواکارییەکانی پێویست بە ڕاستکردنەوەی کارمەند تۆمار بکە. هەر پێوەرێک بە ڕوونی پێناسە بکە: ناردنی فۆڕم هەمیشە واتای پشتڕاستکردنەوەی حجز نییە. وازهێنان لە تەواوکردنی هەنگاوەکان لەگەڵ چاوپێکەوتن یان تێبینییەکانی پشتیوانی پێداچوونەوەی بۆ بکە تا ژمارەکان لە بارودۆخی خۆیاندا تێبگەیت. تەنها لەبەر ئەوەی ئامرازێکی شیکاری ڕێگەت پێ دەدات، داتای کەسی کۆ مەکەرەوە.", "پێش بڵاوکردنەوە، بەروارێکی پێداچوونەوە، بەرپرسێک و یاسایەکی بڕیاردان دیاری بکە. بەڵگەکان لەوانەیە پشتگیری باشترکردنی هەنگاوێکی ناڕوون، فراوانکردنی خزمەتگوزاری، هێشتنەوەی کارێکی دەستی یان ڕاگرتنی گەشەپێدانی زیاتر بکەن. ژمارەی سەردانەکان بە تەنها ناتوانێت هەڵبژاردەی دروستت نیشان بدات."], "sourceIds": ["benefits"]}], "conclusion": "پێش سپاردنی گەشەپێدان، وەسفی کێشەکە، تێبینییەکانی توێژینەوە، ڕێڕەوێکی سنووردار بۆ وەشانی یەکەم و پلانی پێوانەکردن ئامادە بکە. ئەم بەڵگانە بنەمایەکی کرداری دەدەن بە تۆ و هاوبەشە تەکنیکییەکەت بۆ بڕیاردان لەسەر ئەوەی چی دروست بکەن، سەرەتا چی تاقی بکەنەوە و سەرکەوتن چی دەگەیەنێت."}}'::jsonb);
INSERT INTO articles (slug,category,published_at,published,sort_order,sources,translations) VALUES ('website-pwa-or-native-app','engineering','2026-09-06',true,1,'[{"id": "pwa-definition", "title": "MDN — What is a progressive web app?", "url": "https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/What_is_a_progressive_web_app"}, {"id": "offline-data", "title": "web.dev — Offline data", "url": "https://web.dev/learn/pwa/offline-data"}, {"id": "capabilities", "title": "web.dev — Capabilities", "url": "https://web.dev/learn/pwa/capabilities"}, {"id": "apple-push", "title": "Apple Developer — Sending web push notifications in web apps and browsers", "url": "https://developer.apple.com/documentation/usernotifications/sending-web-push-notifications-in-web-apps-and-browsers"}, {"id": "android-quality", "title": "Android Developers — Core app quality guidelines", "url": "https://developer.android.com/docs/quality-guidelines/core-app-quality"}]'::jsonb,'{"en": {"title": "Website, PWA, or native app: how to choose for your product", "description": "Compare a responsive website, progressive web app, and native mobile app using real tasks, offline needs, device capabilities, and maintenance.", "excerpt": "The right platform follows the job your customers need to do. Compare access, repeat use, offline behaviour, and device requirements before committing to a build.", "takeaways": ["Start with a real user journey and target devices, then choose the platform that can support them.", "Treat offline operation and device integration as specific requirements to prototype and test.", "Compare delivery and ongoing maintenance together; an installable product still needs a reason to be used."], "sections": [{"id": "define-options", "heading": "Understand what the three options mean", "paragraphs": ["A responsive website adapts its interface to different screen sizes and is accessed through a browser. A progressive web app, or PWA, uses web technology with additional app-like behaviour. MDN describes features such as installation and offline operation, with support varying by environment. A native app is built for a particular operating system and its platform interfaces.", "These categories do not decide product quality. A website can have accounts and complex workflows. A PWA still needs a well-designed web experience. A native app still needs useful content and reliable services. Distinguish platform choice from implementation choice: a shared mobile framework may produce iOS and Android apps, while leaving platform-specific work to maintain."], "sourceIds": ["pwa-definition"]}, {"id": "access-frequency", "heading": "Examine how people arrive and why they return", "paragraphs": ["Write down the first three steps of the customer journey. Someone opening a restaurant menu from a shared link may want information immediately. Asking them to install software before reading it creates another step. A technician using a work tool throughout the day may value a dedicated app and persistent local work.", "Assess frequency, urgency, and discovery separately. Frequent use can support the case for installation, but it does not automatically require native development. A public website and a specialist staff app can also coexist. Decide which audience each interface serves, then consider whether shared accounts, data, and administration make the combined operating model manageable."]}, {"id": "offline-contract", "heading": "Specify exactly what must work offline", "paragraphs": ["Offline is a set of behaviours to design. List what people must read, create, change, and send without a connection. web.dev explains that offline web data requires storage management, including limits and persistence. Cached pages alone do not define a dependable working process.", "For a field inspection tool, specify whether yesterday’s job list remains available, whether a new photo is saved locally, and how an inspector knows a report has reached the server. Design pending, failed, and synced states. Decide how duplicate submissions and conflicting edits are resolved.", "Local browser data can be removed, including by the user. Do not treat it as the only copy of important records. Test closing and reopening the app, expired sessions, interrupted uploads, and reconnecting after a long gap. Native apps also need explicit data and synchronisation design; installation does not make a transaction succeed offline."], "sourceIds": ["offline-data"]}, {"id": "device-capabilities", "heading": "Test the capability that could change the decision", "paragraphs": ["Replace “needs phone features” with a precise list: capture a photo, read a particular scanner, share a document, or receive a notification. web.dev advises detecting feature support because web capabilities vary across devices and browsers. Check the required behaviour on the actual combinations your audience uses.", "Notifications illustrate the importance of details. Apple documents web push for Home Screen web apps on iOS 16.4 or later. That does not mean every visitor in an ordinary browser tab has the same notification experience. Include installation and permission steps in the prototype.", "If reliable background work or specialist hardware is central, commission a focused technical experiment before approving the full interface. Test denial of permissions and unavailable features. Prefer a platform only after the essential task works under its real restrictions."], "sourceIds": ["capabilities", "apple-push"]}, {"id": "operating-cost", "heading": "Compare the work after release", "paragraphs": ["Ask for a maintenance plan alongside the build estimate. Websites and PWAs need browser testing, dependency updates, hosting, security work, and content operations. A PWA also needs careful handling of cached versions and offline data. Mobile apps add platform release and compatibility work; shared code does not remove every difference.", "Android’s quality guidance calls for current platform compatibility, SDK maintenance, and testing on representative devices. Use this as a reminder to budget for ongoing engineering. Ask who investigates crashes, tests an operating-system update, handles account access, and releases fixes.", "Compare approaches over the same period and scope. Include backend services, administration tools, testing devices, support, and ownership of accounts. Avoid universal cost ratios: the complexity of your actual workflow may matter more than the platform label."], "sourceIds": ["android-quality"]}, {"id": "decision-examples", "heading": "Use scenarios to expose the tradeoffs", "paragraphs": ["The following examples are decision exercises, not claims about existing clients:"], "bullets": ["A Baghdad consultancy needs service pages, project explanations, and enquiry forms. A responsive website is a plausible starting point because the core journey begins with reading and contacting the team.", "A distributor’s repeat customers browse an order catalogue on phones and laptops. A PWA may fit if the required browser support, installation experience, and offline catalogue behaviour are verified. Stock confirmation still requires a defined server interaction.", "A field team depends on a specific scanner and work continuing when the interface is closed. Evaluate a native app against those exact hardware and background requirements before deciding. A separate web dashboard may suit office staff."]}, {"id": "decision-checklist", "heading": "Record a decision you can revisit", "paragraphs": ["Use this checklist to make a reviewable choice:"], "bullets": ["1. Name the primary user task, entry point, and expected frequency of use.", "2. List supported devices, operating systems, browsers, languages, and accessibility needs.", "3. Describe the exact offline and device behaviours required, with acceptable fallbacks.", "4. Prototype the highest-risk requirement on representative real devices.", "5. Compare initial delivery and ongoing ownership using the same scope.", "6. Record the choice, its assumptions, and the evidence that would justify changing it."]}], "conclusion": "Choose the platform that can reliably complete the user’s task within your operating constraints. Keep the reasoning visible: if customer behaviour or a required capability changes, you should be able to revisit the decision without restarting the product conversation."}, "ar": {"title": "موقع أم تطبيق ويب تقدّمي أم تطبيق أصلي: كيف تختار لمنتجك؟", "description": "قارن بين الموقع المتجاوب وتطبيق الويب التقدّمي والتطبيق الأصلي وفق مهام المستخدم والعمل دون اتصال وإمكانات الجهاز والصيانة.", "excerpt": "تتبع المنصة المناسبة المهمة التي يحتاج عملاؤك إلى إنجازها. قارن طريقة الوصول وتكرار الاستخدام والعمل دون اتصال ومتطلبات الجهاز قبل بدء التطوير.", "takeaways": ["ابدأ برحلة استخدام فعلية وأجهزة محددة، ثم اختر المنصة القادرة على دعمها.", "حوّل العمل دون اتصال والتكامل مع الجهاز إلى متطلبات دقيقة تُختبر بنموذج عملي.", "قارن تكلفة التسليم والصيانة معاً؛ قابلية التثبيت لا تكفي لتجعل الناس يستخدمون المنتج."], "sections": [{"id": "define-options", "heading": "افهم معنى الخيارات الثلاثة", "paragraphs": ["يكيّف الموقع المتجاوب واجهته مع أحجام الشاشات المختلفة ويُفتح في المتصفح. يستخدم تطبيق الويب التقدّمي، أو PWA، تقنيات الويب مع سلوكيات إضافية تشبه التطبيقات. تصف MDN مزايا مثل التثبيت والعمل دون اتصال، مع اختلاف الدعم بحسب بيئة التشغيل. أما التطبيق الأصلي فيُبنى لنظام تشغيل محدد وواجهاته البرمجية.", "لا تحسم هذه التصنيفات جودة المنتج. يمكن للموقع أن يحتوي على حسابات وإجراءات معقدة. ويظل تطبيق الويب التقدّمي بحاجة إلى تجربة ويب جيدة التصميم، كما يحتاج التطبيق الأصلي إلى محتوى مفيد وخدمات موثوقة. ميّز أيضاً بين اختيار المنصة واختيار طريقة التنفيذ: قد ينتج إطار تطوير مشترك تطبيقَي iOS وAndroid، مع بقاء أجزاء خاصة بكل منصة تحتاج إلى صيانة."], "sourceIds": ["pwa-definition"]}, {"id": "access-frequency", "heading": "افحص كيف يصل الناس ولماذا يعودون", "paragraphs": ["اكتب الخطوات الثلاث الأولى في رحلة العميل. قد يريد شخص يفتح قائمة مطعم من رابط مُرسل الوصول إلى المعلومات فوراً؛ وطلب تثبيت برنامج قبل قراءتها يضيف خطوة أخرى. أما الفني الذي يستخدم أداة عمل طوال اليوم فقد يستفيد من تطبيق مخصص يحتفظ بعمله محلياً.", "قيّم تكرار الاستخدام والاستعجال وطريقة اكتشاف الخدمة بصورة منفصلة. قد يدعم الاستخدام المتكرر الحاجة إلى التثبيت، لكنه لا يفرض التطوير الأصلي تلقائياً. ويمكن الجمع بين موقع عام وتطبيق متخصص للموظفين. حدّد جمهور كل واجهة، ثم قيّم ما إذا كانت الحسابات والبيانات والإدارة المشتركة تجعل تشغيل الحلّين معاً قابلاً للإدارة."]}, {"id": "offline-contract", "heading": "حدّد بدقة ما يجب أن يعمل دون اتصال", "paragraphs": ["العمل دون اتصال مجموعة من السلوكيات التي تحتاج إلى تصميم. اذكر ما يجب أن يستطيع الناس قراءته وإنشاءه وتعديله وإرساله عند انقطاع الشبكة. تشرح web.dev أن بيانات الويب دون اتصال تحتاج إلى إدارة للتخزين، بما يشمل الحدود واستمرارية الاحتفاظ بالبيانات. تخزين الصفحات مؤقتاً وحده لا يحدّد سير عمل موثوقاً.", "في أداة للفحص الميداني، حدّد ما إذا كانت قائمة مهام الأمس ستبقى متاحة، وما إذا كانت الصورة الجديدة تُحفظ محلياً، وكيف يعرف المفتش أن التقرير وصل إلى الخادم. صمّم حالات واضحة لما هو معلّق أو فاشل أو متزامن، وقرّر كيفية معالجة الإرسال المكرر والتعديلات المتعارضة.", "يمكن إزالة بيانات المتصفح المحلية، بما في ذلك حذفها من المستخدم. لا تجعلها النسخة الوحيدة للسجلات المهمة. اختبر إغلاق التطبيق وفتحه، وانتهاء الجلسات، وانقطاع رفع الملفات، وعودة الاتصال بعد مدة طويلة. تحتاج التطبيقات الأصلية أيضاً إلى تصميم صريح للبيانات والمزامنة؛ فالتثبيت لا يجعل المعاملة تنجح دون اتصال."], "sourceIds": ["offline-data"]}, {"id": "device-capabilities", "heading": "اختبر الإمكانية التي قد تغيّر القرار", "paragraphs": ["استبدل عبارة «نحتاج ميزات الهاتف» بقائمة محددة: التقاط صورة، أو القراءة من ماسح معيّن، أو مشاركة مستند، أو تلقي إشعار. تنصح web.dev بالتحقق من دعم الميزة، لأن إمكانات الويب تختلف باختلاف الأجهزة والمتصفحات. اختبر السلوك المطلوب على تركيبات الأجهزة والأنظمة التي يستخدمها جمهورك فعلاً.", "توضح الإشعارات أهمية التفاصيل. توثّق Apple دعم إشعارات الويب لتطبيقات الويب المضافة إلى الشاشة الرئيسية على iOS 16.4 أو أحدث. ولا يعني ذلك أن كل زائر في تبويب متصفح عادي يحصل على تجربة الإشعارات نفسها. أدرج التثبيت وطلب الإذن ضمن النموذج التجريبي.", "إذا كان العمل الموثوق في الخلفية أو التعامل مع أجهزة متخصصة أساسياً، فنفّذ تجربة تقنية مركزة قبل اعتماد الواجهة كاملة. اختبر رفض الأذونات وعدم توافر الميزات. رجّح منصة فقط بعد التحقق من إنجاز المهمة الأساسية في ظل قيودها الفعلية."], "sourceIds": ["capabilities", "apple-push"]}, {"id": "operating-cost", "heading": "قارن العمل المطلوب بعد الإصدار", "paragraphs": ["اطلب خطة صيانة إلى جانب تقدير تكلفة التطوير. تحتاج المواقع وتطبيقات الويب التقدّمية إلى اختبار المتصفحات وتحديث الاعتماديات والاستضافة والعمل الأمني وإدارة المحتوى. ويحتاج تطبيق الويب التقدّمي أيضاً إلى إدارة دقيقة للنسخ المخزنة مؤقتاً وبيانات العمل دون اتصال. تضيف تطبيقات الهاتف أعمال إصدار وتوافق خاصة بالمنصة؛ ومشاركة الشيفرة لا تلغي جميع الفروق.", "تدعو إرشادات جودة Android إلى التوافق مع النظام الحالي وصيانة حزم التطوير والاختبار على أجهزة تمثل المستخدمين. اعتبر ذلك تذكيراً بضرورة تخصيص ميزانية للهندسة المستمرة. اسأل من يحقق في الأعطال، ويختبر تحديث نظام التشغيل، ويدير الوصول إلى الحسابات، وينشر الإصلاحات.", "قارن البدائل خلال المدة نفسها وبالنطاق نفسه. أدرج الخدمات الخلفية وأدوات الإدارة وأجهزة الاختبار والدعم وملكية الحسابات. تجنّب نسب التكلفة العامة؛ فقد يكون تعقيد سير العمل الفعلي أكثر تأثيراً من اسم المنصة."], "sourceIds": ["android-quality"]}, {"id": "decision-examples", "heading": "استخدم سيناريوهات تُظهر المفاضلات", "paragraphs": ["الأمثلة التالية تمارين لاتخاذ القرار، وليست وصفاً لعملاء حاليين:"], "bullets": ["شركة استشارية في بغداد تحتاج صفحات للخدمات وشرحاً للمشاريع ونماذج للاستفسار. يُعد الموقع المتجاوب نقطة بداية معقولة لأن الرحلة الأساسية تبدأ بالقراءة والتواصل مع الفريق.", "عملاء موزّع يعودون باستمرار لتصفّح دليل طلبات على الهواتف والحواسيب. قد يناسبهم تطبيق ويب تقدّمي إذا جرى التحقق من دعم المتصفحات وتجربة التثبيت وتصفّح الدليل دون اتصال. ويظل تأكيد المخزون بحاجة إلى تفاعل محدد مع الخادم.", "فريق ميداني يعتمد على ماسح معيّن واستمرار العمل عندما تكون الواجهة مغلقة. قيّم التطبيق الأصلي وفق متطلبات الجهاز والعمل في الخلفية قبل اتخاذ القرار. وقد تناسب لوحة تحكم ويب منفصلة موظفي المكتب."]}, {"id": "decision-checklist", "heading": "دوّن قراراً يمكنك مراجعته", "paragraphs": ["استخدم هذه القائمة لتحويل التفضيلات المتنافسة إلى قرار واضح يمكن مراجعته:"], "bullets": ["١. سمِّ مهمة المستخدم الأساسية ونقطة دخوله ومعدل الاستخدام المتوقع.", "٢. اذكر الأجهزة وأنظمة التشغيل والمتصفحات واللغات واحتياجات إمكانية الوصول التي ستدعمها.", "٣. صِف بدقة سلوك العمل دون اتصال وإمكانات الجهاز المطلوبة، مع البدائل المقبولة.", "٤. اختبر المتطلب الأعلى مخاطرة بنموذج عملي على أجهزة حقيقية تمثل الجمهور.", "٥. قارن التسليم الأولي ومسؤوليات التشغيل المستمر باستخدام النطاق نفسه.", "٦. سجّل الاختيار وافتراضاته والأدلة التي تبرّر تغييره مستقبلاً."]}], "conclusion": "اختر المنصة التي تنجز مهمة المستخدم بصورة موثوقة ضمن قيود التشغيل لديك. احتفظ بأسباب القرار واضحة؛ فإذا تغيّر سلوك العملاء أو إحدى الإمكانات المطلوبة، أمكنك مراجعة الاختيار دون إعادة نقاش المنتج من البداية."}, "ckb": {"title": "ماڵپەڕ، ئەپی وێبی پێشکەوتوو یان ئەپی ڕەسەن: چۆن بۆ بەرهەمەکەت هەڵدەبژێریت؟", "description": "ماڵپەڕی گونجاو لەگەڵ شاشە، ئەپی وێبی پێشکەوتوو و ئەپی ڕەسەن بەپێی ئەرکی بەکارهێنەر، کاری ئۆفلاین، توانای ئامێر و چاکسازی بەراورد بکە.", "excerpt": "پلاتفۆڕمی گونجاو بەو ئەرکەوە پەیوەستە کە کڕیارەکانت دەیانەوێت ئەنجامی بدەن. پێش گەشەپێدان، دەستگەیشتن، دووبارە بەکارهێنان، کاری ئۆفلاین و پێداویستییەکانی ئامێر بەراورد بکە.", "takeaways": ["بە ڕێڕەوێکی ڕاستەقینەی بەکارهێنان و ئامێرە دیاریکراوەکان دەست پێ بکە، پاشان پلاتفۆڕمی گونجاو هەڵبژێرە.", "کاری ئۆفلاین و پەیوەستبوون بە ئامێر بکە بە پێداویستیی ورد کە بتوانرێت نموونەی بۆ دروست بکرێت و تاقی بکرێتەوە.", "ڕادەستکردن و چاکسازیی بەردەوام پێکەوە بەراورد بکە؛ بەرهەمێکی دامەزراو هێشتا پێویستی بە هۆکارێکە بۆ بەکارهێنان."], "sections": [{"id": "define-options", "heading": "بزانە هەر یەک لە سێ هەڵبژاردەکە چی دەگەیەنێت", "paragraphs": ["ماڵپەڕی ڕیسپۆنسیڤ ڕووکارەکەی لەگەڵ قەبارەی جیاوازی شاشە دەگونجێنێت و لە ڕێگەی وێبگەڕەوە دەکرێتەوە. ئەپی وێبی پێشکەوتوو، یان PWA، تەکنەلۆژیای وێب بەکار دەهێنێت و هەڵسوکەوتی زیاتری هاوشێوەی ئەپ پێوە زیاد دەکات. MDN باس لە دامەزراندن و کارکردنی ئۆفلاین دەکات، بە پشتگیرییەک کە بەپێی ژینگەی بەکارهێنان دەگۆڕێت. ئەپی ڕەسەن بۆ سیستەمی کارپێکردنێکی دیاریکراو و ڕووکاری بەرنامەسازیی ئەو پلاتفۆڕمە دروست دەکرێت.", "ئەم پۆلێنکردنانە کوالێتیی بەرهەم دیاری ناکەن. ماڵپەڕ دەتوانێت هەژمار و ڕەوتی کاری ئاڵۆزی هەبێت. PWA هێشتا پێویستی بە ئەزموونێکی باشی وێب هەیە، و ئەپی ڕەسەنیش پێویستی بە ناوەڕۆکی بەسوود و خزمەتگوزاریی جێی متمانە هەیە. هەڵبژاردنی پلاتفۆڕم لە شێوازی جێبەجێکردن جیا بکەرەوە: چوارچێوەیەکی هاوبەش دەتوانێت ئەپی iOS و Android دروست بکات، بەڵام کاری تایبەت بە هەر پلاتفۆڕمێک دەمێنێت کە پێویستی بە چاکسازی هەیە."], "sourceIds": ["pwa-definition"]}, {"id": "access-frequency", "heading": "بپشکنە خەڵک چۆن دەگەن و بۆچی دەگەڕێنەوە", "paragraphs": ["سێ هەنگاوی یەکەمی ڕێڕەوی کڕیار بنووسە. کەسێک کە لیستی خواردنی چێشتخانەیەک لە بەستەرێکی نێردراو دەکاتەوە، لەوانەیە زانیارییەکەی دەستبەجێ بوێت. داواکردنی دامەزراندنی نەرمەکاڵا پێش خوێندنەوە هەنگاوێکی زیاتر زیاد دەکات. بەڵام تەکنیککارێک کە بە درێژایی ڕۆژ ئامرازێکی کار بەکار دەهێنێت، لەوانەیە لە ئەپێکی تایبەت و هەڵگرتنی کاری خۆی لەسەر ئامێر سوود ببینێت.", "دووبارەبوونەوەی بەکارهێنان، پەلە و شێوازی دۆزینەوەی خزمەتگوزاری بە جیا هەڵبسەنگێنە. بەکارهێنانی زۆر دەتوانێت پشتگیری دامەزراندن بکات، بەڵام بە خۆکار پێویستی بە گەشەپێدانی ئەپی ڕەسەن دروست ناکات. ماڵپەڕێکی گشتی و ئەپێکی تایبەت بە کارمەندانیش دەتوانن پێکەوە هەبن. دیاری بکە هەر ڕووکارێک بۆ کێیە، پاشان بزانە هاوبەشکردنی هەژمار، داتا و بەڕێوەبردن کارکردن بە هەردووکیانەوە ئاسان دەکات یان نا."]}, {"id": "offline-contract", "heading": "بە وردی دیاری بکە چی دەبێت بەبێ ئینتەرنێت کار بکات", "paragraphs": ["کاری ئۆفلاین کۆمەڵێک هەڵسوکەوتە کە دەبێت دیزاین بکرێت. لیستێک بنووسە بۆ ئەوەی خەڵک دەبێت بەبێ پەیوەندی چی بخوێننەوە، دروست بکەن، بگۆڕن و بنێرن. web.dev ڕوون دەکاتەوە کە داتای ئۆفلاینی وێب پێویستی بە بەڕێوەبردنی هەڵگرتن هەیە، لەوانە سنووری بۆشایی و بەردەوامیی مانەوەی داتا. هەڵگرتنی پەڕەکان لە کاش بە تەنها ڕەوتێکی کاری جێی متمانە پێک ناهێنێت.", "بۆ ئامرازێکی پشکنینی مەیدانی، دیاری بکە ئایا لیستی ئەرکەکانی دوێنێ بەردەست دەمێنێت، وێنەی نوێ لەسەر ئامێر هەڵدەگیرێت و پشکنەر چۆن دەزانێت ڕاپۆرتەکە گەیشتووەتە ڕاژەکار. دۆخی چاوەڕوان، سەرنەکەوتوو و هاوکاتکراو دیزاین بکە. بڕیار بدە چۆن ناردنی دووبارە و دەستکارییە ناکۆکەکان چارەسەر دەکرێن.", "داتای ناوخۆی وێبگەڕ دەتوانرێت بسڕدرێتەوە، لەوانە لەلایەن خودی بەکارهێنەرەوە. مەیکە بە تەنها کۆپیی تۆمارە گرنگەکان. داخستن و کردنەوەی ئەپ، بەسەرچوونی دانیشتنی هەژمار، پچڕانی بارکردنی فایل و گەڕانەوەی پەیوەندی دوای ماوەیەکی درێژ تاقی بکەرەوە. ئەپە ڕەسەنەکانیش پێویستیان بە دیزاینی ڕوونی داتا و هاوکاتکردن هەیە؛ دامەزراندن وا ناکات مامەڵەیەک بەبێ پەیوەندی سەرکەوتوو بێت."], "sourceIds": ["offline-data"]}, {"id": "device-capabilities", "heading": "ئەو توانایە تاقی بکەرەوە کە دەتوانێت بڕیارەکە بگۆڕێت", "paragraphs": ["لەبری «پێویستمان بە تایبەتمەندییەکانی مۆبایلە»، لیستێکی ورد بنووسە: وێنەگرتن، خوێندنەوە لە سکانەرێکی دیاریکراو، هاوبەشکردنی بەڵگەنامە یان وەرگرتنی ئاگادارکردنەوە. web.dev پێشنیار دەکات پشتگیریی تایبەتمەندی بپشکنرێت، چونکە تواناکانی وێب لە نێوان ئامێر و وێبگەڕەکاندا جیاوازن. هەڵسوکەوتی پێویست لەسەر ئەو تێکەڵەی ئامێر و سیستەمانە تاقی بکەرەوە کە بەکارهێنەرەکانت بەڕاستی بەکاریان دەهێنن.", "ئاگادارکردنەوە گرنگیی وردەکارییەکان نیشان دەدات. بەڵگەنامەکانی Apple پشتگیریی Web Push بۆ ئەپە وێبییە زیادکراوەکانی سەر شاشەی سەرەکی لە iOS 16.4 یان نوێتر تۆمار دەکەن. ئەمە واتای ئەوە نییە کە هەر سەردانکەرێک لە تابی ئاسایی وێبگەڕ هەمان ئەزموونی ئاگادارکردنەوەی هەیە. هەنگاوەکانی دامەزراندن و داواکردنی مۆڵەت لە نموونەکەدا جێ بکەرەوە.", "ئەگەر کاری جێی متمانە لە پاشبنەما یان بەکارهێنانی ئامێری تایبەت بنەڕەتییە، پێش پەسەندکردنی هەموو ڕووکارەکە تاقیکردنەوەیەکی تەکنیکیی دیاریکراو ئەنجام بدە. ڕەتکردنەوەی مۆڵەت و نەبوونی تایبەتمەندییەکان تاقی بکەرەوە. کاتێک پلاتفۆڕمێک پێش بخە کە ئەرکە سەرەکییەکە لەژێر سنووردارییە ڕاستەقینەکانی کار بکات."], "sourceIds": ["capabilities", "apple-push"]}, {"id": "operating-cost", "heading": "کاری دوای بڵاوکردنەوە بەراورد بکە", "paragraphs": ["لەگەڵ خەمڵاندنی تێچووی دروستکردن، داوای پلانی چاکسازی بکە. ماڵپەڕ و PWA پێویستیان بە تاقیکردنەوەی وێبگەڕ، نوێکردنەوەی پاکێجە بەکارهاتووەکان، هۆستینگ، کاری ئاسایش و بەڕێوەبردنی ناوەڕۆک هەیە. PWA هەروەها پێویستی بە مامەڵەی ورد هەیە لەگەڵ وەشانە هەڵگیراوەکان لە کاش و داتای ئۆفلاین. ئەپی مۆبایل کاری بڵاوکردنەوە و گونجانی تایبەت بە پلاتفۆڕم زیاد دەکات؛ کۆدی هاوبەش هەموو جیاوازییەکان لانا‌بات.", "ڕێنمایی کوالێتیی Android جەخت لە گونجان لەگەڵ سیستەمی هەنووکەیی، نوێکردنەوەی ئامرازەکانی گەشەپێدان و تاقیکردنەوە لەسەر ئامێری نوێنەرایەتیی بەکارهێنەران دەکاتەوە. ئەمە وەک بیرخستنەوەی تەرخانکردنی بودجە بۆ کاری تەکنیکیی بەردەوام بەکار بهێنە. بپرسە کێ هۆکاری تێکچوون دەدۆزێتەوە، نوێکردنەوەی سیستەمی کارپێکردن تاقی دەکاتەوە، دەستگەیشتن بە هەژمارەکان بەڕێوە دەبات و چاککردنەوەکان بڵاو دەکاتەوە.", "ڕێبازەکان بۆ هەمان ماوە و هەمان سنووری کار بەراورد بکە. خزمەتگوزارییەکانی بەشی پشتەوە، ئامرازەکانی بەڕێوەبردن، ئامێری تاقیکردنەوە، پشتیوانی و خاوەندارێتیی هەژمارەکان تێدا بژمێرە. لە ڕێژەی گشتیی تێچوو دوور بکەوە؛ ئاڵۆزیی ڕەوتی کاری ڕاستەقینەت لەوانەیە لە ناوی پلاتفۆڕمەکە گرنگتر بێت."], "sourceIds": ["android-quality"]}, {"id": "decision-examples", "heading": "بە سیناریۆکان خاڵەکانی بەراورد ڕوون بکەرەوە", "paragraphs": ["ئەم نموونانە مەشقی بڕیاردانن، نە باسکردنی کڕیاری هەنووکەیی:"], "bullets": ["کۆمپانیایەکی ڕاوێژکاری لە بەغدا پێویستی بە پەڕەی خزمەتگوزاری، ڕوونکردنەوەی پڕۆژەکان و فۆڕمی پرسیار هەیە. ماڵپەڕێکی ڕیسپۆنسیڤ دەستپێکێکی گونجاوە، چونکە ڕێڕەوی سەرەکی بە خوێندنەوە و پەیوەندیکردن بە تیمەکە دەست پێ دەکات.", "کڕیارە دووبارەگەڕاوەکانی دابەشکەرێک کەتەلۆگی داواکاری لەسەر مۆبایل و لاپتۆپ دەبینن. PWA لەوانەیە گونجاو بێت، ئەگەر پشتگیریی وێبگەڕ، ئەزموونی دامەزراندن و کارکردنی ئۆفلاینی کەتەلۆگەکە پشتڕاست بکرێنەوە. پشتڕاستکردنەوەی کۆگا هێشتا پێویستی بە مامەڵەیەکی دیاریکراو لەگەڵ ڕاژەکار هەیە.", "تیمێکی مەیدانی پشت بە سکانەرێکی دیاریکراو و بەردەوامبوونی کار لە کاتی داخراوبوونی ڕووکار دەبەستێت. پێش بڕیاردان ئەپی ڕەسەن بەپێی ئەو پێداویستییە وردانەی ئامێر و پاشبنەما هەڵبسەنگێنە. داشبۆردێکی جیاوازی وێب لەوانەیە بۆ کارمەندانی نووسینگە گونجاو بێت."]}, {"id": "decision-checklist", "heading": "بڕیارێک تۆمار بکە کە بتوانیت پێداچوونەوەی بۆ بکەیت", "paragraphs": ["ئەم لیستە بەکار بهێنە بۆ ئەوەی بۆچوونە جیاوازەکان بگۆڕیت بۆ هەڵبژاردەیەکی ڕوون و شیاوی پێداچوونەوە:"], "bullets": ["١. ئەرکی سەرەکیی بەکارهێنەر، خاڵی دەستپێک و دووبارەبوونەوەی چاوەڕوانکراوی بەکارهێنان دیاری بکە.", "٢. ئامێر، سیستەمی کارپێکردن، وێبگەڕ، زمان و پێداویستییەکانی دەستڕاگەیشتنی پشتگیریکراو بنووسە.", "٣. هەڵسوکەوتی وردی ئۆفلاین و توانای پێویستی ئامێر باس بکە، لەگەڵ جێگرەوە پەسەندکراوەکان.", "٤. پێداویستییە پڕمەترسییەکە بە نموونەیەکی کرداری لەسەر ئامێری ڕاستەقینەی نوێنەرایەتیی بەکارهێنەران تاقی بکەرەوە.", "٥. ڕادەستکردنی سەرەتایی و بەرپرسیاریی بەردەوام بەپێی هەمان سنووری کار بەراورد بکە.", "٦. هەڵبژاردەکە، گریمانەکانی و ئەو بەڵگانە تۆمار بکە کە گۆڕینی لە داهاتوودا پاساو دەدەن."]}], "conclusion": "ئەو پلاتفۆڕمە هەڵبژێرە کە بتوانێت لە چوارچێوەی سنووردارییەکانی بەڕێوەبردنتدا ئەرکی بەکارهێنەر بە شێوەیەکی جێی متمانە تەواو بکات. هۆکارەکانی بڕیارەکە ڕوون بهێڵەوە؛ ئەگەر ڕەفتاری کڕیار یان توانایەکی پێویست گۆڕا، بتوانیت بڕیارەکە بپشکنیتەوە بەبێ دەستپێکردنەوەی گفتوگۆی بەرهەم لە سفرەوە."}}'::jsonb);
INSERT INTO articles (slug,category,published_at,published,sort_order,sources,translations) VALUES ('secure-software-launch-checklist','engineering','2026-09-06',true,2,'[{"id": "asvs", "title": "OWASP Application Security Verification Standard", "url": "https://owasp.org/www-project-application-security-verification-standard/"}, {"id": "authentication", "title": "OWASP Authentication Cheat Sheet", "url": "https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"}, {"id": "authorization", "title": "OWASP Authorization Cheat Sheet", "url": "https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html"}, {"id": "secrets", "title": "OWASP Secrets Management Cheat Sheet", "url": "https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html"}, {"id": "logging", "title": "OWASP Logging Cheat Sheet", "url": "https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html"}]'::jsonb,'{"en": {"title": "A practical security checklist for your next software launch", "description": "Prepare a software release with practical checks for access controls, secrets, restore drills, monitoring, and accountable launch decisions.", "excerpt": "A successful build is only one part of launch readiness. Use this guide to turn security and recovery concerns into evidence, owners, and a clear release decision.", "takeaways": ["Verify critical controls with realistic failure cases, including access across different customer accounts.", "Prove that backups restore a usable service and that alerts reach someone who can act.", "Make launch blockers explicit and give every accepted risk an owner and a review date."], "sections": [{"id": "define-readiness", "heading": "Define what must be true before release", "paragraphs": ["Map the service you are launching: public routes, privileged operations, customer data, external services, and deployment path. Ask what happens if a stranger, ordinary member, or compromised administrator uses each entry point. This creates a review boundary without pretending a short checklist covers every application.", "OWASP ASVS provides requirements for developing and verifying application security controls. Select the requirements relevant to your system and record the version used. Then build a release worksheet with a requirement, test evidence, owner, and decision for each item. Keep evidence attached to the release being reviewed; a test against last month''s configuration does not establish today''s readiness."], "sourceIds": ["asvs"]}, {"id": "authentication", "heading": "Exercise the entire account lifecycle", "paragraphs": ["Authentication establishes identity. OWASP recommends defenses such as multifactor authentication, login throttling, and renewed identity checks for sensitive actions. Use maintained authentication components and choose protections appropriate to the account''s authority.", "Walk through registration, sign-in, recovery, invitation acceptance, sign-out, and account removal as connected journeys. Invite a colleague, revoke the invitation, and verify the original link cannot create membership. Repeat after changing an email address or removing an administrator. Give these transitions the same attention as the login form.", "Record the expected session behavior for each transition before testing it. Include a lost-device scenario so the support process does not become an unreviewed route around the controls."], "sourceIds": ["authentication"]}, {"id": "authorization", "heading": "Test permissions at the data boundary", "paragraphs": ["Authorization decides what an identified person may do. OWASP recommends least privilege, denying access by default, and checking permission on every request in a trusted server-side location.", "Create two test organizations with separate records. Sign in to one and attempt to read, edit, export, and delete the other''s records through the API. Repeat with a read-only member and a removed member. Include uploaded files, background jobs, and bulk operations.", "Write the expected outcome as a small permission matrix. A disabled button is useful feedback, but your evidence should show that the underlying request is rejected. Preserve these cases as regression checks when membership rules or data queries change."], "sourceIds": ["authorization"]}, {"id": "secrets-and-configuration", "heading": "Make secrets and production configuration reviewable", "paragraphs": ["OWASP''s secrets guidance covers controlled storage, limited access, rotation, and auditing. Keep production credentials out of source code, browser bundles, and diagnostic output; revoke exposed credentials rather than treating deletion as containment.", "Prepare a credential inventory containing purpose, environment, owner, consumers, and the replacement procedure. Inspect the generated build as well as repository settings: ask which values reach the browser and which remain on the server. Rehearse replacing one low-risk service credential in a test environment.", "Compare the release configuration with its intended production settings. Check debug behavior, administrative routes, dependency updates, and external integrations. Save the reviewed configuration reference with the deployment record."], "sourceIds": ["secrets"]}, {"id": "recovery", "heading": "Restore a working service", "paragraphs": ["OWASP recommends protecting backups and regularly testing restoration for secrets-management systems. Apply the same evidence-first approach to the application data and configuration your service needs.", "Agree on how much recent work the business could afford to lose and how long essential operations could be unavailable. Design the backup schedule and recovery procedure around those answers. These business choices cannot be settled by a generic backup frequency.", "Run a drill in an isolated environment. Restore the database, required files, and configuration, then complete a representative customer workflow. Measure the time and record missing dependencies. Prevent the restored environment from sending real customer messages or triggering production integrations. Have a second operator follow the written instructions."], "sourceIds": ["secrets"]}, {"id": "observability", "heading": "Connect signals to a response", "paragraphs": ["OWASP''s logging guidance includes authentication events and authorization failures, while excluding or protecting sensitive values such as passwords and access tokens. Decide what your team needs to investigate an event without collecting whole request bodies by default.", "For each essential workflow, choose a signal that exposes failure: a checkout error, stalled processing job, or unsuccessful upload. Add useful operational context such as the release identifier and a request reference. Define the person who receives the alert and the first action they should take.", "Trigger a controlled failure and follow it from the customer-visible symptom to the alert and investigation. Check what happens outside normal working hours. A dashboard without a response path leaves a gap."], "sourceIds": ["logging"]}, {"id": "launch-decision", "heading": "Use a short launch decision checklist", "paragraphs": ["Prioritize findings by plausible harm, reachability, and recovery options. Treat cross-customer data access or an exposed production credential as a reason to stop the affected release. For a lower-impact issue, document the mitigation, responsible owner, and review date instead of leaving an ambiguous promise to fix it later.", "Before approving the release, confirm the following:"], "bullets": ["The critical user journeys and denied-access cases have current evidence.", "An operator has completed the recovery drill and recorded its result.", "A controlled failure reached the named responder.", "The deployment and rollback procedure addresses database changes as well as application code.", "Accepted risks have explicit owners, dates, and agreed limits on exposure."]}], "conclusion": "Keep the release worksheet after launch and update it when the system changes. Readiness is an evidence-based decision about this release, its users, and the team''s ability to detect and recover from failure. Revisit that decision as the service evolves."}, "ar": {"title": "قائمة عملية للتحقق من أمان إطلاق البرمجيات", "description": "جهّز إصدارك بفحوص عملية للصلاحيات والأسرار واستعادة النسخ الاحتياطية والمراقبة، مع معايير واضحة لاتخاذ قرار الإطلاق.", "excerpt": "نجاح بناء التطبيق جزء واحد من جاهزية الإطلاق. يساعدك هذا الدليل على تحويل متطلبات الأمان والتعافي إلى أدلة ومسؤوليات وقرار إصدار واضح.", "takeaways": ["اختبر الضوابط الأساسية بحالات فشل واقعية، ومنها محاولات الوصول بين حسابات عملاء مختلفين.", "أثبت أن النسخ الاحتياطية تعيد خدمة قابلة للاستخدام وأن التنبيهات تصل إلى شخص يستطيع التصرف.", "حدّد ما يمنع الإطلاق، وعيّن مسؤولاً وموعد مراجعة لكل خطر مقبول."], "sections": [{"id": "define-readiness", "heading": "حدّد شروط الجاهزية قبل الإصدار", "paragraphs": ["ابدأ بالخدمة التي ستطلقها فعلاً: المسارات العامة، والعمليات ذات الصلاحيات المرتفعة، وبيانات العملاء، والخدمات الخارجية، ومسار النشر. اسأل ماذا يمكن أن يحدث إذا استخدم كل نقطة دخول شخص مجهول، أو عضو عادي، أو مهاجم استولى على حساب مدير. بهذه الطريقة تحدّد نطاقاً مفيداً للمراجعة، من دون افتراض أن قائمة قصيرة تغطي كل تطبيق.", "يوفّر معيار OWASP ASVS متطلبات لتطوير ضوابط أمان التطبيقات والتحقق منها. اختر ما يلائم نظامك وسجّل نسخة المعيار المستخدمة. أنشئ بعدها ورقة مراجعة تتضمن المتطلب ودليل الاختبار والمسؤول والقرار لكل بند. اربط الأدلة بالإصدار الذي تراجعه؛ فالاختبار الذي أُجري على إعدادات الشهر الماضي لا يثبت جاهزية إعدادات اليوم."], "sourceIds": ["asvs"]}, {"id": "authentication", "heading": "اختبر دورة حياة الحساب كاملة", "paragraphs": ["تثبت المصادقة هوية المستخدم. توصي OWASP بضوابط مثل المصادقة متعددة العوامل، وتقييد محاولات الدخول، وإعادة التحقق من الهوية عند العمليات الحساسة. استخدم مكونات مصادقة تحظى بصيانة مستمرة، واختر الحماية المناسبة لسلطة الحساب.", "اختبر التسجيل والدخول والاسترداد وقبول الدعوة والخروج وإزالة الحساب بوصفها رحلة مترابطة. مثلاً، أرسل دعوة إلى زميل، ثم ألغها وتحقق من أن الرابط الأصلي لا يزال عاجزاً عن إنشاء عضوية. أعد الرحلة بعد تغيير عنوان البريد أو إزالة أحد المديرين. تحتاج هذه الانتقالات إلى اهتمام يماثل الاهتمام بنموذج الدخول.", "دوّن السلوك المتوقع للجلسات عند كل انتقال قبل اختباره. أضف سيناريو فقدان الجهاز، حتى لا تصبح إجراءات الدعم طريقاً غير مراجع لتجاوز الضوابط."], "sourceIds": ["authentication"]}, {"id": "authorization", "heading": "اختبر الصلاحيات عند الوصول إلى البيانات", "paragraphs": ["يحدّد التفويض ما يُسمح للمستخدم المعروف بفعله. توصي OWASP بمبدأ أقل صلاحية، والمنع الافتراضي، والتحقق من الإذن في كل طلب ضمن موضع موثوق على الخادم.", "أنشئ مؤسستين تجريبيتين بسجلات منفصلة. ادخل إلى إحداهما وحاول قراءة سجلات الأخرى وتعديلها وتصديرها وحذفها عبر واجهة API. كرّر ذلك بعضو للقراءة فقط وآخر أُزيلت عضويته. أدرج في التمرين الملفات المرفوعة والمهام الخلفية والعمليات الجماعية.", "دوّن النتيجة المتوقعة في مصفوفة صلاحيات صغيرة. تعطيل الزر مفيد لشرح الواجهة، لكن الدليل المطلوب هو رفض الطلب نفسه. احتفظ بهذه الحالات كاختبارات لمنع عودة الخلل عند تغيير قواعد العضوية أو استعلامات البيانات."], "sourceIds": ["authorization"]}, {"id": "secrets-and-configuration", "heading": "اجعل الأسرار وإعدادات الإنتاج قابلة للمراجعة", "paragraphs": ["تتناول إرشادات OWASP للأسرار التخزين المنضبط، وتقييد الوصول، والتدوير، والتدقيق. أبقِ بيانات اعتماد الإنتاج خارج الشيفرة وحزم المتصفح والمخرجات التشخيصية. ألغِ بيانات الاعتماد المكشوفة؛ حذفها وحده لا يحتوي التسريب.", "أعدّ سجلاً لبيانات الاعتماد يوضّح الغرض والبيئة والمسؤول والخدمات المستخدمة لها وخطوات استبدالها. افحص ملفات البناء الناتجة إضافة إلى إعدادات المستودع: ما القيم التي تصل إلى المتصفح، وما الذي يبقى على الخادم؟ تمرّن على استبدال بيانات اعتماد خدمة منخفضة المخاطر في بيئة اختبار.", "قارن إعدادات الإصدار بإعدادات الإنتاج المطلوبة. راجع وضع التصحيح ومسارات الإدارة وتحديثات الاعتماديات والتكاملات الخارجية. احفظ مرجع الإعدادات التي راجعتها مع سجل النشر."], "sourceIds": ["secrets"]}, {"id": "recovery", "heading": "استعد خدمة تعمل", "paragraphs": ["توصي OWASP بحماية النسخ الاحتياطية واختبار استعادتها دورياً في أنظمة إدارة الأسرار. طبّق المنهج نفسه، القائم على الإثبات، على بيانات تطبيقك وإعداداته اللازمة لتشغيل الخدمة.", "اتفق مع أصحاب العمل على مقدار العمل الحديث الذي يمكن تحمّل فقدانه، والمدة التي يمكن خلالها توقّف العمليات الأساسية. صمّم جدول النسخ الاحتياطي وخطة التعافي على هذا الأساس. هذه قرارات تخص العمل؛ وتيرة نسخ عامة لا تستطيع اتخاذها نيابة عنك.", "نفّذ تمريناً في بيئة معزولة. استعد قاعدة البيانات والملفات والإعدادات الضرورية، ثم أكمل رحلة استخدام تمثّل عمل العميل. قِس الزمن وسجّل الاعتماديات الناقصة. امنع البيئة المستعادة من إرسال رسائل حقيقية للعملاء أو تشغيل تكاملات الإنتاج. اطلب من مشغّل ثانٍ تنفيذ الخطوات المكتوبة."], "sourceIds": ["secrets"]}, {"id": "observability", "heading": "اربط إشارات المراقبة باستجابة عملية", "paragraphs": ["تشمل إرشادات التسجيل لدى OWASP أحداث المصادقة وفشل التفويض، مع استبعاد القيم الحساسة أو حمايتها، مثل كلمات المرور ورموز الوصول. حدّد المعلومات اللازمة للتحقيق من دون جمع محتوى الطلبات كاملاً بصورة افتراضية.", "اختر لكل رحلة أساسية إشارة تكشف الفشل: خطأ إتمام شراء، أو مهمة معالجة متوقفة، أو رفع ملف غير ناجح. أضف سياقاً تشغيلياً مفيداً مثل معرّف الإصدار ومرجع الطلب. حدّد الشخص الذي يتلقى التنبيه وأول إجراء ينبغي أن يتخذه.", "أحدث فشلاً مضبوطاً وتابعه من الأثر الذي يراه العميل إلى التنبيه والتحقيق. تحقّق مما يحدث خارج ساعات العمل المعتادة. وجود لوحة مراقبة من دون مسار للاستجابة يترك فجوة."], "sourceIds": ["logging"]}, {"id": "launch-decision", "heading": "استخدم قائمة قصيرة لاتخاذ قرار الإطلاق", "paragraphs": ["رتّب الملاحظات بحسب الضرر المحتمل، وإمكان الوصول إلى الخلل، وخيارات التعافي. اعتبر الوصول إلى بيانات عميل آخر أو كشف بيانات اعتماد الإنتاج سبباً لإيقاف الإصدار المتأثر. أما المشكلة الأقل أثراً، فوثّق تخفيفها والمسؤول عنها وموعد مراجعتها بدلاً من وعد غامض بإصلاحها لاحقاً.", "قبل اعتماد الإصدار، تأكّد من الآتي:"], "bullets": ["توجد أدلة حديثة لرحلات المستخدم الأساسية وحالات رفض الوصول.", "أكمل مشغّل تمرين التعافي وسجّل نتيجته.", "وصل تنبيه الفشل المضبوط إلى المستجيب المحدّد.", "تغطي خطة النشر والتراجع تغييرات قاعدة البيانات إلى جانب شيفرة التطبيق.", "لكل خطر مقبول مسؤول وموعد وحدود متفق عليها للتعرض له."]}], "conclusion": "احتفظ بورقة مراجعة الإصدار بعد الإطلاق وحدّثها عندما يتغير النظام. الجاهزية قرار يستند إلى أدلة تخص هذا الإصدار ومستخدميه وقدرة الفريق على اكتشاف الفشل والتعافي منه. أعد تقييم هذا القرار مع تطوّر الخدمة."}, "ckb": {"title": "لیستی پشکنینی کرداری بۆ بڵاوکردنەوەی پارێزراوی نەرمەکاڵا", "description": "بە پشکنینی دەسەڵات، نهێنییەکان، گەڕاندنەوەی پاشەکەوت و چاودێری، وەشانی نەرمەکاڵاکەت بۆ بڵاوکردنەوە ئامادە بکە.", "excerpt": "سەرکەوتنی دروستکردنی ئەپ تەنها بەشێکە لە ئامادەیی بۆ بڵاوکردنەوە. ئەم ڕێبەرە یارمەتیت دەدات داواکارییەکانی ئاسایش و گەڕاندنەوە بکەیتە بەڵگە و بەرپرسیارێتی و بڕیارێکی ڕوون.", "takeaways": ["کۆنترۆڵە سەرەکییەکان بە حاڵەتی شکستی واقعی تاقی بکەرەوە، لەوانە هەوڵی دەستگەیشتن لەنێوان هەژماری کڕیارە جیاوازەکان.", "بیسەلمێنە کە پاشەکەوت خزمەتگوزارییەکی بەکارهێنراو دەگەڕێنێتەوە و ئاگادارکردنەوە دەگاتە کەسێک کە بتوانێت هەنگاو بنێت.", "ئەو کێشانەی ڕێگری لە بڵاوکردنەوە دەکەن ڕوون بکەرەوە؛ بۆ هەر مەترسییەکی پەسەندکراو بەرپرس و بەرواری پێداچوونەوە دابنێ."], "sections": [{"id": "define-readiness", "heading": "پێش بڵاوکردنەوە مەرجەکانی ئامادەیی دیاری بکە", "paragraphs": ["لەو خزمەتگوزارییەوە دەست پێ بکە کە بەڕاستی بڵاوی دەکەیتەوە: ڕێڕەوە گشتییەکان، کردارە بەدەسەڵاتەکان، داتای کڕیاران، خزمەتگوزارییە دەرەکییەکان و ڕێڕەوی بڵاوکردنەوە. بپرسە چی ڕوودەدات ئەگەر کەسێکی نەناسراو، ئەندامێکی ئاسایی یان هێرشبەرێک کە هەژماری بەڕێوەبەرێکی داگیر کردووە، هەر خاڵێکی چوونەژوورەوە بەکاربهێنێت. ئەمە سنوورێکی بەسوود بۆ پێداچوونەوە دادەنێت، بەبێ ئەوەی وا دابنێیت لیستێکی کورت هەموو ئەپێک دەگرێتەوە.", "پێوەری OWASP ASVS داواکاری بۆ پەرەپێدان و پشکنینی کۆنترۆڵەکانی ئاسایشی ئەپ دابین دەکات. ئەوانە هەڵبژێرە کە لەگەڵ سیستەمەکەت دەگونجێن و وەشانی بەکارهاتوو تۆمار بکە. پاشان خشتەیەکی پێداچوونەوە دروست بکە کە داواکاری، بەڵگەی تاقیکردنەوە، بەرپرس و بڕیار بۆ هەر بڕگەیەک هەبێت. بەڵگەکان بەو وەشانەوە ببەستە کە پشکنینی دەکەیت؛ تاقیکردنەوەی ڕێکخستنەکانی مانگی ڕابردوو ئامادەیی ئەمڕۆ ناسەلمێنێت."], "sourceIds": ["asvs"]}, {"id": "authentication", "heading": "هەموو قۆناغەکانی ژیانی هەژمار تاقی بکەرەوە", "paragraphs": ["پشتڕاستکردنەوەی ناسنامە دیاری دەکات بەکارهێنەر کێیە. OWASP ڕێوشوێنی وەک پشتڕاستکردنەوەی چەند هۆکاری، سنووردارکردنی هەوڵەکانی چوونەژوورەوە و دووبارە پشکنینی ناسنامە بۆ کردارە هەستیارەکان پێشنیار دەکات. پێکهاتەی ناسنامە بەکاربهێنە کە بەردەوام چاکسازی بۆ دەکرێت و پاراستنەکە لەگەڵ دەسەڵاتی هەژمارەکە بگونجێنە.", "تۆماربوون، چوونەژوورەوە، گەڕاندنەوەی هەژمار، قبووڵکردنی بانگهێشت، چوونەدەرەوە و سڕینەوەی هەژمار وەک گەشتێکی پەیوەست تاقی بکەرەوە. بۆ نموونە، هاوکارێک بانگهێشت بکە، پاشان بانگهێشتەکە هەڵبوەشێنەوە و دڵنیابە بەستەرە کۆنەکە ناتوانێت ئەندامێتی دروست بکات. دوای گۆڕینی ئیمەیڵ یان لابردنی بەڕێوەبەرێک، تاقیکردنەوەکە دووبارە بکەرەوە. ئەم گۆڕانکارییانە هەمان گرنگی فۆڕمی چوونەژوورەوەیان هەیە.", "پێش تاقیکردنەوە بنووسە لە هەر گۆڕانێکدا دانیشتنی بەکارهێنەر دەبێت چ ڕەفتارێکی هەبێت. حاڵەتی ونبوونی ئامێرێکیش زیاد بکە، تاکو پرۆسەی پشتگیری نەبێتە ڕێڕەوێکی پشکنین‌نەکراو بۆ تێپەڕاندنی کۆنترۆڵەکان."], "sourceIds": ["authentication"]}, {"id": "authorization", "heading": "دەسەڵات لە سنووری دەستگەیشتن بە داتا تاقی بکەرەوە", "paragraphs": ["ڕێگەپێدان دیاری دەکات بەکارهێنەرێکی ناسراو مافی چی هەیە. OWASP کەمترین دەسەڵاتی پێویست، ڕەتکردنەوە بە شێوەی بنەڕەتی و پشکنینی مۆڵەت لە هەر داواکارییەکدا لە شوێنێکی متمانەپێکراوی سێرڤەر پێشنیار دەکات.", "دوو ڕێکخراوی تاقیکردنەوە بە تۆماری جیاواز دروست بکە. بە هەژماری یەکێکیان بچۆ ژوورەوە و لە ڕێگەی API هەوڵی خوێندنەوە، دەستکاریکردن، هەناردەکردن و سڕینەوەی تۆمارەکانی ئەوی تر بدە. بە ئەندامێکی تەنها خوێندنەوە و ئەندامێک کە ئەندامێتییەکەی لابراوە دووبارەی بکەرەوە. فایلە بارکراوەکان، کارەکانی پاشبنەما و کردارە بەکۆمەڵەکانیش بخەرە ناو تاقیکردنەوەکە.", "ئەنجامی چاوەڕوانکراو لە خشتەیەکی بچووکی دەسەڵاتدا بنووسە. ناچالاککردنی دوگمە ڕوونکردنەوەیەکی باشە بۆ ڕووکار، بەڵام بەڵگەکەت دەبێت ڕەتکردنەوەی خودی داواکارییەکە پیشان بدات. ئەم حاڵەتانە وەک پشکنینی ڕێگری لە گەڕانەوەی هەڵە بپارێزە کاتێک یاساکانی ئەندامێتی یان پرسیارەکانی داتا دەگۆڕدرێن."], "sourceIds": ["authorization"]}, {"id": "secrets-and-configuration", "heading": "نهێنییەکان و ڕێکخستنەکانی ژینگەی کارکردن ڕوون بکەرەوە", "paragraphs": ["ڕێنمایی OWASP بۆ نهێنییەکان هەڵگرتنی کۆنترۆڵکراو، دەستگەیشتنی سنووردار، گۆڕین و پشکنین دەگرێتەوە. زانیارییە نهێنییەکانی دەستگەیشتن بە ژینگەی کارکردن لە کۆدی سەرچاوە، پاکێجی وێبگەڕ و دەرئەنجامی دیباگ دوور بخەرەوە. ئەو کلیلانەی ئاشکرا بوون پووچەڵ بکەرەوە؛ تەنها سڕینەوەیان ناتوانێت لیکەکە کۆنترۆڵ بکات.", "لیستێکی زانیارییەکانی دەستگەیشتن ئامادە بکە کە مەبەست، ژینگە، بەرپرس، خزمەتگوزارییە بەکارهێنەرەکان و ڕێگای جێگرتنەوەیان تێدا بێت. جگە لە ڕێکخستنەکانی کۆگای کۆد، فایلە دروستکراوەکانیش بپشکنە: کام بەها دەگاتە وێبگەڕ و کامەیان لە سێرڤەر دەمێنێتەوە؟ لە ژینگەی تاقیکردنەوەدا جێگرتنەوەی کلیلی خزمەتگوزارییەکی کەم‌مەترسی ڕاهێنان بکە.", "ڕێکخستنەکانی وەشان لەگەڵ ڕێکخستنی خوازراوی ژینگەی کارکردن بەراورد بکە. دۆخی دیباگ، ڕێڕەوەکانی بەڕێوەبردن، نوێکردنەوەی پەیوەستەکان و تێکەڵکردن لەگەڵ خزمەتگوزارییە دەرەکییەکان بپشکنە. ئاماژەی ڕێکخستنە پشکنراوەکە لەگەڵ تۆماری بڵاوکردنەوە هەڵبگرە."], "sourceIds": ["secrets"]}, {"id": "recovery", "heading": "خزمەتگوزارییەکی کارا بگەڕێنەوە", "paragraphs": ["OWASP پاراستنی پاشەکەوتەکان و تاقیکردنەوەی بەردەوامی گەڕاندنەوەیان بۆ سیستەمی بەڕێوەبردنی نهێنییەکان پێشنیار دەکات. هەمان ڕێبازی پشتبەستووبەبەڵگە بۆ داتا و ڕێکخستنەکانی ئەپەکەت بەکاربهێنە.", "لەگەڵ بەرپرسانی کار ڕێک بکەوە کە چەند لە کاری نوێ دەکرێت لەدەست بچێت و چەند کات دەکرێت کردارە سەرەکییەکان بوەستن. خشتەی کاتی پاشەکەوت و ڕێوشوێنی گەڕاندنەوە لەسەر ئەم وەڵامانە دابنێ. ئەمانە بڕیاری کارن؛ خشتەیەکی گشتی پاشەکەوت ناتوانێت بۆت بڕیار بدات.", "لە ژینگەیەکی جیاکراوەدا ڕاهێنان بکە. بنکەدراوە، فایلە پێویستەکان و ڕێکخستن بگەڕێنەوە، پاشان گەشتێکی نوێنەرایەتی بەکارهێنانی کڕیار تەواو بکە. کاتەکە بپێوە و ئەو پێداویستییانە تۆمار بکە کە ون بوون. ڕێگری بکە لەوەی ژینگە گەڕێندراوەکە پەیامی ڕاستەقینە بۆ کڕیار بنێرێت یان تێکەڵکردنەکانی ژینگەی کارکردن چالاک بکات. داوا لە کارپێکەرێکی دووەم بکە ڕێنماییە نووسراوەکان جێبەجێ بکات."], "sourceIds": ["secrets"]}, {"id": "observability", "heading": "نیشانەکانی چاودێری بە وەڵامدانەوە ببەستە", "paragraphs": ["ڕێنمایی تۆمارکردنی OWASP ڕووداوەکانی پشتڕاستکردنەوەی ناسنامە و شکستی ڕێگەپێدان دەگرێتەوە، لەگەڵ لابردن یان پاراستنی بەها هەستیارەکانی وەک وشەی نهێنی و تۆکنی دەستگەیشتن. دیاری بکە تیمەکەت بۆ لێکۆڵینەوە چی پێویستە، بەبێ ئەوەی ناوەڕۆکی تەواوی هەموو داواکارییەک بە شێوەی بنەڕەتی کۆ بکاتەوە.", "بۆ هەر گەشتێکی سەرەکی نیشانەیەک هەڵبژێرە کە شکست ئاشکرا بکات: هەڵەی تەواوکردنی کڕین، کاری پرۆسێسکردنی وەستاو یان بارکردنی سەرنەکەوتوو. زانیارییەکی کارگێڕی بەسوود وەک ناسێنەری وەشان و ئاماژەی داواکاری زیاد بکە. دیاری بکە ئاگادارکردنەوە دەگاتە کێ و یەکەم هەنگاوی ئەو کەسە چییە.", "شکستێکی کۆنترۆڵکراو دروست بکە و لەو نیشانەیەی کڕیار دەیبینێت تا ئاگادارکردنەوە و لێکۆڵینەوە بەدوایدا بچۆ. بپشکنە لە دەرەوەی کاتی ئاسایی کاردا چی ڕوودەدات. داشبۆردێک بەبێ ڕێڕەوی وەڵامدانەوە بۆشایی بەجێ دەهێڵێت."], "sourceIds": ["logging"]}, {"id": "launch-decision", "heading": "لیستێکی کورت بۆ بڕیاری بڵاوکردنەوە بەکاربهێنە", "paragraphs": ["دۆزراوەکان بەپێی زیانی ئەگەردار، ئاسانکاری دەستگەیشتن بە کێشەکە و هەڵبژاردەکانی گەڕاندنەوە ڕیز بکە. دەستگەیشتن بە داتای کڕیارێکی تر یان ئاشکرابوونی کلیلی ژینگەی کارکردن بە هۆکاری ڕاگرتنی وەشانی کاریگەر دابنێ. بۆ کێشەیەکی کەم‌کاریگەر، چارەی کەمکردنەوەی مەترسی، بەرپرس و بەرواری پێداچوونەوە بنووسە؛ بەڵێنێکی ناڕوون بۆ دواتر بەجێ مەهێڵە.", "پێش پەسەندکردنی وەشان، لەمانە دڵنیابە:"], "bullets": ["گەشتە سەرەکییەکانی بەکارهێنەر و حاڵەتەکانی ڕەتکردنەوەی دەستگەیشتن بەڵگەی نوێیان هەیە.", "کارپێکەرێک ڕاهێنانی گەڕاندنەوەی تەواو کردووە و ئەنجامەکەی تۆمار کردووە.", "ئاگادارکردنەوەی شکستی کۆنترۆڵکراو گەیشتووەتە وەڵامدەرەوەی دیاریکراو.", "پلانی بڵاوکردنەوە و گەڕانەوە گۆڕانکارییەکانی بنکەدراوە و کۆدی ئەپ دەگرێتەوە.", "مەترسییە پەسەندکراوەکان بەرپرس، بەروار و سنووری ڕێککەوتوویان هەیە."]}], "conclusion": "دوای بڵاوکردنەوە خشتەی پێداچوونەوە بپارێزە و لەگەڵ گۆڕانی سیستەم نوێی بکەرەوە. ئامادەیی بڕیارێکی پشتبەستووبەبەڵگەیە دەربارەی ئەم وەشانە و بەکارهێنەرەکانی و توانای تیم بۆ دۆزینەوە و چاکبوونەوە لە شکست. لەگەڵ پەرەسەندنی خزمەتگوزاری، ئەم بڕیارە دووبارە هەڵبسەنگێنە."}}'::jsonb);
INSERT INTO articles (slug,category,published_at,published,sort_order,sources,translations) VALUES ('website-performance-and-technical-seo','growth','2026-09-06',true,3,'[{"id": "web-vitals", "title": "web.dev: Web Vitals", "url": "https://web.dev/articles/vitals"}, {"id": "seo-starter", "title": "Google Search Central: SEO Starter Guide", "url": "https://developers.google.com/search/docs/fundamentals/seo-starter-guide"}, {"id": "canonical", "title": "Google Search Central: Specify a canonical URL", "url": "https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls"}, {"id": "localized", "title": "Google Search Central: Localized versions of your pages", "url": "https://developers.google.com/search/docs/specialty/international/localized-versions"}, {"id": "structured-data", "title": "Google Search Central: General structured data guidelines", "url": "https://developers.google.com/search/docs/appearance/structured-data/sd-policies"}]'::jsonb,'{"en": {"title": "Website performance and technical SEO: a practical review", "description": "Review Core Web Vitals, crawl access, canonical URLs, multilingual pages, and structured data with a practical website improvement checklist.", "excerpt": "Help visitors reach useful content quickly and help search engines understand it. This guide connects performance measurements with discoverability checks for multilingual websites.", "takeaways": ["Measure loading, responsiveness, and layout stability on representative pages and real user journeys.", "Keep internal links, canonical URLs, and language alternatives consistent with the content that actually exists.", "Treat search tools and structured data as evidence and configuration, without promising rankings or rich results."], "sections": [{"id": "reader-and-page", "heading": "Give each page a clear job", "paragraphs": ["Begin with the visitor''s question. A service page should explain the work, scope, and next step. A guide should help someone complete a task or make a decision. Define that job before reviewing technical reports, so performance improvements support a clear user outcome.", "Google''s starter guidance emphasizes useful, original content and discoverable links. Turn that into an editorial review: can a new reader understand the page title, find the answer, and navigate to a relevant next page? For example, connect a launch checklist to the service that helps implement it, using a descriptive link. Avoid creating several near-identical pages simply to vary a search phrase."], "sourceIds": ["seo-starter"]}, {"id": "measure", "heading": "Read the measurements correctly", "paragraphs": ["The good Core Web Vitals thresholds are LCP at or below 2.5 seconds, INP at or below 200 milliseconds, and CLS at or below 0.1. Assess all three at the 75th percentile, separately for mobile and desktop. They describe loading, responsiveness, and visual stability.", "Use field data to understand observed visits and laboratory tests to investigate reproducible problems. A standard Lighthouse page-load test cannot measure INP without interactions. Its performance score is not a replacement for the three field metrics.", "Review the homepage, a service page, a long article, and an interactive form in every language. Record the test date, device conditions, page version, and whether results describe the URL or a broader group. When field data is absent, mark it as missing evidence and continue with controlled tests."], "sourceIds": ["web-vitals"]}, {"id": "fix-bottlenecks", "heading": "Change the bottleneck you can observe", "paragraphs": ["For a slow main-content render, inspect the request sequence: is the delay before the server responds, before the important image is requested, or while the browser prepares to display it? For an unresponsive menu, reproduce the click and inspect the work that follows. For a moving layout, identify the element that displaced the content.", "A practical first pass is to remove assets that serve no current purpose, size images for their displayed role, reserve space for media, and review third-party scripts. Let the trace determine which change deserves priority. Avoid applying every optimization suggestion in a report at once.", "Save before-and-after results under comparable conditions. Complete the original visitor task again, including keyboard use and form validation. A faster page that loses a required interaction still needs repair."]}, {"id": "crawl-and-canonical", "heading": "Check discovery, indexing, and preferred URLs", "paragraphs": ["Use Search Console''s URL Inspection to examine important published pages. Google finds content through links, so confirm that an article is reachable from your site''s navigation or related content. Check that the public page displays the intended text and that a forgotten staging restriction is not hiding it.", "For duplicate URLs, align internal links, sitemap entries, and canonical declarations. Google treats canonical annotations as signals. Robots.txt does not reliably remove a URL from the index, and noindex is not a substitute for consolidating duplicates.", "Create a URL worksheet: intended public address, response, indexability, and canonical target. Investigate contradictions, such as a canonical pointing to a redirect or unrelated homepage. Check crawling, indexing, and canonical selection separately; success in one does not establish success in the others."], "sourceIds": ["seo-starter", "canonical"]}, {"id": "multilingual", "heading": "Review every language as a complete product", "paragraphs": ["Google''s hreflang guidance requires reciprocal references, including each page itself, with fully qualified URLs. Validate supported language and script codes separately from your application''s locale keys; do not assume a key such as ckb is automatically a supported Google hreflang value. Keep canonicals aligned with the page''s language.", "Maintain a mapping between equivalent articles and their published translations. Only advertise an alternative when that complete page exists. Test the language switcher from an article, not only from the homepage, and confirm it preserves the reader''s context.", "For Arabic and Sorani Kurdish, review right-to-left layout, mixed-direction code, punctuation, headings, and mobile navigation. Read the translated examples and calls to action as well as the body. Assign an owner to update all versions when an instruction changes."], "sourceIds": ["localized", "canonical"]}, {"id": "structured-data", "heading": "Describe only what the page actually contains", "paragraphs": ["Google requires structured data to represent visible, relevant content, and correct markup does not guarantee a rich result. Follow the documentation for the particular feature and use the Rich Results Test for technical validation.", "For a guide, verify that the stated author, publication date, title, and related entities match the page. Do not invent ratings, reviews, affiliations, or business details to populate a template. If the content model cannot supply a trustworthy value, remove the unsupported claim.", "Keep a representative markup sample with the template review. Recheck it when the template or content fields change; one successful test cannot cover every future article."], "sourceIds": ["structured-data"]}, {"id": "review-checklist", "heading": "Finish with a repeatable review", "paragraphs": ["Choose a small batch of improvements and record the expected benefit before release. This makes later reviews useful even when traffic is too limited to establish a trend."], "bullets": ["Every reviewed page answers a defined visitor question and has a clear next step.", "Performance evidence identifies the page, device conditions, and data source.", "Important pages are linked, accessible, and free of unintended indexing restrictions.", "Preferred URLs and published language alternatives agree across the site.", "Structured data matches visible facts and passes the relevant technical checks.", "An owner will review errors, user-task completion, and search observations after release."]}], "conclusion": "Performance and technical SEO work best as ongoing maintenance of a useful website. Keep the measurements, fixes, and editorial decisions connected. Improved access and usability create a stronger site, while rankings, indexing, and rich-result appearance remain outcomes you cannot guarantee."}, "ar": {"title": "أداء الموقع والسيو التقني: مراجعة عملية", "description": "راجع مؤشرات أداء الويب والوصول للزحف والروابط الأساسية والصفحات متعددة اللغات والبيانات المنظّمة بقائمة تحسين عملية.", "excerpt": "ساعد الزائر على الوصول سريعاً إلى محتوى مفيد، وساعد محركات البحث على فهمه. يربط هذا الدليل قياس الأداء بفحوص قابلية اكتشاف المواقع متعددة اللغات.", "takeaways": ["قِس التحميل والاستجابة والثبات البصري على صفحات تمثيلية ورحلات استخدام فعلية.", "اجعل الروابط الداخلية والعناوين الأساسية وبدائل اللغات متوافقة مع المحتوى المنشور فعلاً.", "استخدم أدوات البحث والبيانات المنظّمة للفحص والتهيئة من دون وعد بترتيب أو نتائج بحث محسّنة."], "sections": [{"id": "reader-and-page", "heading": "امنح كل صفحة مهمة واضحة", "paragraphs": ["ابدأ بسؤال الزائر. ينبغي لصفحة الخدمة أن تشرح العمل المقدّم ونطاقه والخطوة التالية. وينبغي للدليل أن يساعد القارئ على إنجاز مهمة أو اتخاذ قرار. دوّن هذه المهمة قبل مراجعة التقارير التقنية، كي يخدم تحسين الأداء نتيجة واضحة للمستخدم.", "تركّز إرشادات Google التمهيدية على المحتوى المفيد والأصلي والروابط القابلة للاكتشاف. حوّل ذلك إلى مراجعة تحريرية: هل يفهم القارئ الجديد عنوان الصفحة، ويجد الإجابة، وينتقل إلى صفحة تالية ذات صلة؟ مثلاً، اربط قائمة جاهزية الإطلاق بالخدمة التي تساعد على تنفيذها، مستخدماً وصفاً واضحاً للرابط. تجنّب إنشاء صفحات متشابهة جداً لمجرد تغيير صياغة عبارة بحث."], "sourceIds": ["seo-starter"]}, {"id": "measure", "heading": "اقرأ القياسات بصورة صحيحة", "paragraphs": ["الحدود المصنّفة «جيدة» لمؤشرات أداء الويب الأساسية هي: LCP لا يتجاوز 2.5 ثانية، وINP لا يتجاوز 200 ميلي ثانية، وCLS لا يتجاوز 0.1. قيّم المؤشرات الثلاثة عند المئين 75، مع فصل الهاتف عن الحاسوب. تصف هذه المقاييس التحميل والاستجابة والثبات البصري.", "استخدم بيانات المستخدمين الفعليين لفهم الزيارات المرصودة، والاختبارات المختبرية للتحقيق في مشكلات قابلة للتكرار. اختبار تحميل الصفحة المعتاد في Lighthouse لا يقيس INP من دون تفاعلات. ودرجة الأداء فيه لا تحل محل المقاييس الميدانية الثلاثة.", "جهّز مجموعة مراجعة تضم الصفحة الرئيسية وصفحة خدمة ومقالاً طويلاً وصفحة ذات نموذج تفاعلي، مع تضمين كل لغة. سجّل تاريخ الاختبار وظروف الجهاز ونسخة الصفحة، وما إذا كانت النتيجة تخص الرابط نفسه أو مجموعة أوسع. عند غياب البيانات الميدانية، سجّلها كدليل غير متاح واستمر في الاختبارات المضبوطة."], "sourceIds": ["web-vitals"]}, {"id": "fix-bottlenecks", "heading": "عالج سبب البطء الذي تستطيع رصده", "paragraphs": ["عندما يتأخر عرض المحتوى الرئيسي، افحص تسلسل الطلبات: هل التأخير قبل استجابة الخادم، أم قبل طلب الصورة المهمة، أم أثناء تجهيز المتصفح لعرضها؟ وإذا كانت قائمة التنقل بطيئة الاستجابة، فأعد النقرة وافحص العمل الذي يليها. وعند تحرك التخطيط، حدّد العنصر الذي أزاح المحتوى.", "ابدأ عملياً بإزالة الملفات التي لم تعد تخدم غرضاً، وضبط أحجام الصور بحسب عرضها، وحجز مساحة للوسائط، ومراجعة نصوص الجهات الخارجية. دع أثر التنفيذ يحدّد أولوية التغيير. تجنّب تطبيق كل اقتراح تحسين في التقرير دفعة واحدة.", "احفظ نتيجة قبل التعديل وبعده في ظروف قابلة للمقارنة. ثم أكمل مهمة الزائر الأصلية مجدداً، بما فيها استخدام لوحة المفاتيح والتحقق من صحة النموذج. الصفحة الأسرع التي تفقد تفاعلاً ضرورياً بالخطأ ما زالت تحتاج إلى إصلاح."]}, {"id": "crawl-and-canonical", "heading": "افحص الاكتشاف والفهرسة والعنوان المفضّل", "paragraphs": ["استخدم أداة فحص عنوان URL في Search Console لفحص الصفحات المنشورة المهمة. تعثر Google على المحتوى عبر الروابط؛ لذا تأكّد من إمكان الوصول إلى المقال من التنقل أو المحتوى المرتبط داخل موقعك. راجع ظهور النص المطلوب في الصفحة العامة، وتحقّق من عدم وجود قيد منسي من بيئة الاختبار يخفيها.", "وحّد الروابط الداخلية ومدخلات خريطة الموقع وإعلانات الرابط الأساسي للصفحات ذات العناوين المكررة. تتعامل Google مع إعلانات canonical بوصفها إشارات. ملف robots.txt لا يضمن إزالة الرابط من الفهرس، وnoindex ليس بديلاً عن توحيد النسخ المكررة.", "أنشئ ورقة روابط صغيرة تتضمن العنوان العام المقصود والاستجابة وقابلية الفهرسة والعنوان الأساسي المستهدف. حقّق في التناقضات، مثل رابط أساسي يشير إلى إعادة توجيه أو صفحة رئيسية غير ذات صلة. افحص الزحف والفهرسة واختيار الرابط الأساسي كلّاً على حدة؛ نجاح أحدها لا يثبت نجاح البقية."], "sourceIds": ["seo-starter", "canonical"]}, {"id": "multilingual", "heading": "راجع كل لغة كمنتج مكتمل", "paragraphs": ["تشترط إرشادات Google الخاصة بـhreflang مراجع متبادلة تشمل الصفحة نفسها، مع عناوين URL كاملة. تحقّق من رموز اللغات والكتابة المدعومة بصورة منفصلة عن مفاتيح اللغات في التطبيق؛ لا تفترض أن مفتاحاً مثل ckb مدعوم تلقائياً كقيمة hreflang لدى Google. اجعل الرابط الأساسي متوافقاً مع لغة الصفحة.", "احتفظ بخريطة تربط المقالات المتكافئة بترجماتها المنشورة. لا تعلن عن بديل لغوي إلا عندما تكون صفحته الكاملة موجودة. اختبر مبدّل اللغة من داخل المقال، إضافة إلى الصفحة الرئيسية، وتأكّد من احتفاظه بسياق القارئ.", "في العربية والكردية السورانية، راجع اتجاه التخطيط من اليمين إلى اليسار، والشيفرة ذات الاتجاه المختلط، وعلامات الترقيم، والعناوين، والتنقل على الهاتف. اقرأ الأمثلة المترجمة ودعوات اتخاذ الإجراء إلى جانب النص الأساسي. عيّن مسؤولاً لتحديث جميع النسخ عند تغيير إحدى التعليمات."], "sourceIds": ["localized", "canonical"]}, {"id": "structured-data", "heading": "صِف ما تحتويه الصفحة فعلاً", "paragraphs": ["تشترط Google أن تمثّل البيانات المنظّمة محتوى ظاهراً وذا صلة، ولا يضمن الترميز الصحيح ظهور نتيجة بحث محسّنة. اتبع توثيق الميزة المعنية واستخدم اختبار النتائج الغنية للتحقق التقني.", "في صفحة الدليل، تحقّق من مطابقة الكاتب وتاريخ النشر والعنوان والكيانات المرتبطة لما تعرضه الصفحة. لا تختلق تقييمات أو مراجعات أو انتماءات أو معلومات تجارية لملء قالب. إذا كان نموذج المحتوى لا يوفّر قيمة موثوقة، فأزل الادعاء غير المدعوم.", "احتفظ بعينة تمثيلية من الترميز ضمن مراجعة قالب الصفحة. أعد فحصها عند تغيير القالب أو حقول المحتوى، بدلاً من افتراض أن اختباراً ناجحاً واحداً يغطي كل المقالات المستقبلية."], "sourceIds": ["structured-data"]}, {"id": "review-checklist", "heading": "اختتم بمراجعة قابلة للتكرار", "paragraphs": ["اختر مجموعة صغيرة من التحسينات وسجّل الفائدة المتوقعة قبل الإصدار. بذلك تصبح المراجعة التالية مفيدة حتى عندما تكون الزيارات قليلة ولا تسمح باستخلاص اتجاه بثقة."], "bullets": ["تجيب كل صفحة خضعت للمراجعة عن سؤال محدّد للزائر، وتعرض خطوة تالية واضحة.", "تحدّد أدلة الأداء الصفحة وظروف الجهاز ومصدر البيانات.", "الصفحات المهمة مرتبطة ويمكن الوصول إليها وخالية من قيود الفهرسة غير المقصودة.", "تتوافق العناوين المفضّلة وبدائل اللغات المنشورة في أنحاء الموقع.", "تطابق البيانات المنظّمة الحقائق الظاهرة وتجتاز الفحوص التقنية المناسبة.", "يوجد مسؤول سيراجع الأخطاء وإتمام مهام المستخدم وملاحظات البحث بعد الإصدار."]}], "conclusion": "يحقق العمل على الأداء والسيو التقني أفضل قيمة عندما يكون صيانة مستمرة لموقع مفيد. اربط القياسات بالإصلاحات والقرارات التحريرية. تحسين الوصول وقابلية الاستخدام يقوّي الموقع، أما الترتيب والفهرسة وظهور النتائج المحسّنة فلا يمكن ضمانها."}, "ckb": {"title": "خێرایی ماڵپەڕ و SEOی تەکنیکی: پێداچوونەوەیەکی کرداری", "description": "بە لیستێکی کرداری، پێوەرەکانی وێب، دەستگەیشتنی گەڕۆک، بەستەری سەرەکی، پەڕە فرەزمانەکان و داتای ڕێکخراو بپشکنە.", "excerpt": "یارمەتی سەردانکەر بدە بە خێرایی بگاتە ناوەڕۆکی بەسوود و یارمەتی بزوێنەری گەڕان بدە لێی تێبگات. ئەم ڕێبەرە پێوانەکردنی کارایی بە پشکنینی دۆزینەوەی ماڵپەڕی فرەزمان دەبەستێتەوە.", "takeaways": ["خێرایی باربوون، وەڵامدانەوە و جێگیری بینراو لە پەڕەی نوێنەر و گەشتی واقعی بەکارهێنەر بپێوە.", "بەستەرە ناوخۆییەکان، ناونیشانی سەرەکی و جێگرەوە زمانییەکان لەگەڵ ناوەڕۆکی بەڕاستی بڵاوکراوە بگونجێنە.", "ئامرازەکانی گەڕان و داتای ڕێکخراو بۆ پشکنین و ڕێکخستن بەکاربهێنە، بەبێ بەڵێنی پلە یان ئەنجامی دەوڵەمەندی گەڕان."], "sections": [{"id": "reader-and-page", "heading": "بۆ هەر پەڕەیەک ئەرکێکی ڕوون دابنێ", "paragraphs": ["لە پرسیاری سەردانکەرەوە دەست پێ بکە. پەڕەی خزمەتگوزاری دەبێت کاری پێشکەشکراو، سنوورەکەی و هەنگاوی دواتر ڕوون بکاتەوە. ڕێبەرێک دەبێت یارمەتی خوێنەر بدات ئەرکێک تەواو بکات یان بڕیار بدات. پێش خوێندنەوەی ڕاپۆرتە تەکنیکییەکان ئەو ئەرکە بنووسە، تاکو چاکسازی کارایی خزمەت بە ئەنجامێکی دیاریکراوی بەکارهێنەر بکات.", "ڕێنمایی سەرەتایی Google گرنگی بە ناوەڕۆکی ڕەسەن و بەسوود و بەستەری دۆزراوە دەدات. ئەمە بکە بە پێداچوونەوەی نووسین: ئایا خوێنەرێکی نوێ لە ناونیشانی پەڕەکە تێدەگات، وەڵام دەدۆزێتەوە و دەتوانێت بچێتە پەڕەیەکی پەیوەندیداری دواتر؟ بۆ نموونە، بە بەستەرێکی وەسفکەر لیستی ئامادەیی بڵاوکردنەوە بەو خزمەتگوزارییە ببەستە کە یارمەتی جێبەجێکردنی دەدات. تەنها بۆ گۆڕینی دەستەواژەی گەڕان، چەند پەڕەیەکی زۆر لەیەکچوو دروست مەکە."], "sourceIds": ["seo-starter"]}, {"id": "measure", "heading": "پێوانەکان بە دروستی بخوێنەوە", "paragraphs": ["سنووری «باش» بۆ پێوەرە سەرەکییەکانی وێب ئەمانەن: LCP تا 2.5 چرکە، INP تا 200 میلی‌چرکە و CLS تا 0.1. هەرسێکیان لە پلەی سەدی 75 هەڵسەنگێنە، بە جیاکردنەوەی مۆبایل و کۆمپیوتەر. ئەمانە باربوون، وەڵامدانەوە و جێگیری بینراو وەسف دەکەن.", "داتای بەکارهێنەری ڕاستەقینە بۆ تێگەیشتن لە سەردانە تۆمارکراوەکان و تاقیکردنەوەی تاقیگەیی بۆ لێکۆڵینەوەی کێشەی دووبارەکراوە بەکاربهێنە. تاقیکردنەوەی ئاسایی بارکردنی پەڕە لە Lighthouse، بەبێ کارلێک ناتوانێت INP بپێوێت. نمرەی کارایی ئەو جێگرەوەی هەرسێ پێوەرە مەیدانییەکە نییە.", "کۆمەڵەیەکی پێداچوونەوە ئامادە بکە کە پەڕەی سەرەکی، پەڕەی خزمەتگوزاری، وتارێکی درێژ و پەڕەیەک بە فۆڕمی کارلێککار لەخۆ بگرێت. هەموو زمانەکان بخەرە ناوی. بەرواری تاقیکردنەوە، بارودۆخی ئامێر، وەشانی پەڕە و ئەوە تۆمار بکە کە ئەنجامەکان تایبەتن بە هەمان URL یان کۆمەڵەیەکی فراوانتر. ئەگەر داتای مەیدانی نەبوو، وەک بەڵگەی بەردەست‌نەبوو تۆماری بکە و بە تاقیکردنەوەی کۆنترۆڵکراو بەردەوام بە."], "sourceIds": ["web-vitals"]}, {"id": "fix-bottlenecks", "heading": "ئەو هۆکارەی خاویی چارەسەر بکە کە دەیبینیت", "paragraphs": ["ئەگەر ناوەڕۆکی سەرەکی بە هێواشی پیشان دەدرێت، زنجیرەی داواکارییەکان بپشکنە: دواخستنەکە پێش وەڵامی سێرڤەرە، پێش داواکردنی وێنە گرنگەکەیە یان لە کاتی ئامادەکردنی بۆ پیشاندان لەلایەن وێبگەڕەوەیە؟ ئەگەر لیستی ڕێنیشاندەر هێواشە، کرتەکە دووبارە بکەرەوە و کاری دوای ئەو بپشکنە. ئەگەر ڕووکار دەجوڵێت، ئەو پێکهاتەیە بدۆزەوە کە ناوەڕۆکەکەی لە شوێنی خۆی جوڵاندووە.", "دەستپێکێکی کرداری ئەوەیە فایلە بێ‌مەبەستەکان لاببەیت، قەبارەی وێنەکان بەپێی شێوەی پیشاندانیان ڕێک بخەیت، شوێن بۆ میدیا تەرخان بکەیت و سکریپتی لایەنی سێیەم بپشکنیت. با تۆماری جێبەجێکردن دیاری بکات کام گۆڕانکاری پێشینەی هەیە. هەموو پێشنیارەکانی ڕاپۆرتەکە بە یەکجار جێبەجێ مەکە.", "ئەنجامی پێش و دوای گۆڕانکاری لە بارودۆخی بەراوردکراودا هەڵبگرە. پاشان ئەرکە سەرەتاییەکەی سەردانکەر دووبارە تەواو بکە، لەگەڵ بەکارهێنانی تەختەکلیل و پشکنینی دروستی فۆڕم. پەڕەیەکی خێراتر کە بە هەڵە کارلێکێکی پێویست لەدەست دەدات، هێشتا پێویستی بە چاکسازی هەیە."]}, {"id": "crawl-and-canonical", "heading": "دۆزینەوە، ئیندێکسکردن و ناونیشانی پەسەندکراو بپشکنە", "paragraphs": ["ئامرازی URL Inspection لە Search Console بۆ پشکنینی پەڕە گرنگە بڵاوکراوەکان بەکاربهێنە. Google لە ڕێگەی بەستەرەوە ناوەڕۆک دەدۆزێتەوە؛ بۆیە دڵنیابە وتارەکە لە ڕێگەی ڕێنیشاندەر یان ناوەڕۆکی پەیوەندیداری ماڵپەڕەکەتەوە دەستپێدەگات. بپشکنە پەڕە گشتییەکە دەقی مەبەست پیشان دەدات و سنووردارکردنێکی لەبیرکراوی ژینگەی تاقیکردنەوە نایشارێتەوە.", "بۆ URLی دووبارە، بەستەرە ناوخۆییەکان، تۆمارەکانی نەخشەی ماڵپەڕ و دیاریکردنی canonical یەک بخە. Google ئاماژەکانی canonical وەک نیشانە مامەڵەیان لەگەڵ دەکات. robots.txt سڕینەوەی URL لە ئیندێکس دڵنیا ناکاتەوە و noindex جێگرەوەی یەکخستنی پەڕە دووبارەکان نییە.", "خشتەیەکی بچووکی URL دروست بکە: ناونیشانی گشتی مەبەست، وەڵام، توانای ئیندێکسکردن و ئامانجی canonical. لە دژبەیەکبوونەکان بکۆڵەوە؛ بۆ نموونە canonicalێک کە ئاماژە بە ڕەوانەکردنەوە یان پەڕەیەکی سەرەکی نەپەیوەندیدار دەکات. سەردانی گەڕۆک، ئیندێکسکردن و هەڵبژاردنی canonical بە سێ پشکنینی جیاواز دابنێ؛ سەرکەوتنی یەکێکیان سەرکەوتنی ئەوانی تر ناسەلمێنێت."], "sourceIds": ["seo-starter", "canonical"]}, {"id": "multilingual", "heading": "هەر زمانێک وەک بەرهەمێکی تەواو بپشکنە", "paragraphs": ["ڕێنمایی hreflangی Google پەیوەندی دوولایەنە داوا دەکات کە هەر پەڕەیەک خۆیشی بگرێتەوە و URLی تەواوی هەبێت. کۆدی زمان و نووسینی پشتگیریکراو بە جیا لە کلیلی زمانی ئەپەکەت بپشکنە؛ وا مەزانە کلیلێکی وەک ckb خۆکارانە وەک بەهای hreflang لەلایەن Google پشتگیری دەکرێت. canonical لەگەڵ زمانی پەڕەکە بگونجێنە.", "نەخشەیەک لەنێوان وتارە هاوتاکان و وەرگێڕانە بڵاوکراوەکانیان بپارێزە. تەنها کاتێک جێگرەوەیەکی زمانی ڕابگەیەنە کە پەڕەی تەواوی هەبێت. گۆڕەری زمان لە ناو وتارێکیشەوە تاقی بکەرەوە، نەک تەنها پەڕەی سەرەکی، و دڵنیابە بابەتی خوێنەر دەپارێزێت.", "بۆ عەرەبی و کوردیی سۆرانی، ئاراستەی ڕاست‌بۆچەپ، کۆدی تێکەڵ لە ڕووی ئاراستەوە، نیشانەکانی ڕستەبەندی، ناونیشانەکان و ڕێنیشاندەری مۆبایل بپشکنە. جگە لە دەقی سەرەکی، نموونە وەرگێڕدراوەکان و داواکارییەکانی هەنگاونانیش بخوێنەوە. بەرپرسێک دیاری بکە بۆ نوێکردنەوەی هەموو وەشانەکان کاتێک ڕێنماییەک دەگۆڕێت."], "sourceIds": ["localized", "canonical"]}, {"id": "structured-data", "heading": "تەنها ئەوە وەسف بکە کە بەڕاستی لە پەڕەکەدایە", "paragraphs": ["Google داوا دەکات داتای ڕێکخراو نوێنەرایەتی ناوەڕۆکی بینراو و پەیوەندیدار بکات؛ نیشانەگذاری دروستیش ئەنجامی دەوڵەمەندی گەڕان مسۆگەر ناکات. بەدوای بەڵگەنامەی تایبەتمەندییەکە بکەوە و Rich Results Test بۆ پشکنینی تەکنیکی بەکاربهێنە.", "لە ڕێبەرێکدا، بپشکنە ناوی نووسەر، بەرواری بڵاوکردنەوە، ناونیشان و یەکە پەیوەندیدارەکان لەگەڵ پەڕەکە بگونجێن. بۆ پڕکردنەوەی قاڵب، نمرەدان، هەڵسەنگاندن، سەر بە دامەزراوەبوون یان زانیاری بازرگانی داهێنان مەکە. ئەگەر مۆدێلی ناوەڕۆک ناتوانێت بەهایەکی متمانەپێکراو بدات، بانگەشە پشتگیری‌نەکراوەکە لاببە.", "نموونەیەکی نوێنەری نیشانەگذاری لەگەڵ پێداچوونەوەی قاڵبی پەڕە هەڵبگرە. کاتێک قاڵب یان خانەکانی ناوەڕۆک دەگۆڕێن دووبارەی بپشکنە؛ وا مەزانە یەک تاقیکردنەوەی سەرکەوتوو هەموو وتارەکانی داهاتوو دەگرێتەوە."], "sourceIds": ["structured-data"]}, {"id": "review-checklist", "heading": "بە پێداچوونەوەیەکی دووبارەکراوە کارەکە تەواو بکە", "paragraphs": ["کۆمەڵەیەکی بچووکی چاکسازی هەڵبژێرە و پێش بڵاوکردنەوە سوودی چاوەڕوانکراو تۆمار بکە. ئەمە پێداچوونەوەی دواتر بەسوود دەکات، تەنانەت ئەگەر سەردانەکان زۆر کەم بن بۆ ئەوەی بە دڵنیایی ئاراستەیەک لێیان دەربهێنیت."], "bullets": ["هەر پەڕەیەکی پشکنراو وەڵامی پرسیارێکی دیاریکراوی سەردانکەر دەدات و هەنگاوی دواتری ڕوون هەیە.", "بەڵگەی کارایی پەڕەکە، بارودۆخی ئامێر و سەرچاوەی داتا دیاری دەکات.", "پەڕە گرنگەکان بەستەریان هەیە، دەستپێدەگەن و سنووردارکردنی نەخوازراوی ئیندێکسکردنیان نییە.", "ناونیشانە پەسەندکراوەکان و جێگرەوە زمانییە بڵاوکراوەکان لە سەرانسەری ماڵپەڕ یەکدەگرنەوە.", "داتای ڕێکخراو لەگەڵ ڕاستییە بینراوەکان دەگونجێت و پشکنینە تەکنیکییە پەیوەندیدارەکان تێدەپەڕێنێت.", "بەرپرسێک دوای بڵاوکردنەوە هەڵەکان، تەواوکردنی ئەرکی بەکارهێنەر و تێبینییەکانی گەڕان دەخاتەوە بەر پشکنین."]}], "conclusion": "کارکردن لەسەر کارایی و SEOی تەکنیکی وەک چاکسازی بەردەوامی ماڵپەڕێکی بەسوود باشترین بەها دروست دەکات. پێوانەکان، چاکسازییەکان و بڕیارەکانی نووسین بەیەکەوە ببەستە. باشترکردنی دەستگەیشتن و بەکارهێنان ماڵپەڕ بەهێز دەکات، بەڵام پلە، ئیندێکسکردن و دەرکەوتنی ئەنجامی دەوڵەمەند مسۆگەر ناکرێن."}}'::jsonb);

CREATE TABLE cms_seed_runs (key varchar(80) PRIMARY KEY, completed_at timestamptz NOT NULL DEFAULT now());
INSERT INTO cms_seed_runs (key) SELECT 'legacy-demo-v2' FROM settings WHERE id = 1 AND COALESCE((data->>'seedVersion')::int, 0) >= 2 ON CONFLICT DO NOTHING;
